INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,37,'وما كان يتهيَّأ لأحد أن يأتي بهذا القرآن مِن عند غير الله، لأنه لا يقدر على ذلك أحد من الخلق، ولكن الله أنزله مصدِّقا للكتب التي أنزلها على أنبيائه؛ لأن دين الله واحد، وفي هذا القرآن بيان وتفصيل لما شرعه الله لأمة محمد صلى الله عليه وسلم، لا شك في أن هذا القرآن موحىً من رب العالمين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,38,'بل أيقولون: إن هذا القرآن افتراه محمد من عند نفسه؟ فإنهم يعلمون أنه بشر مثلهم!! قل لهم -أيها الرسول-: فأتوا أنتم بسورة واحدة من جنس هذا القرآن في نظمه وهدايته، واستعينوا على ذلك بكل مَن قَدَرْتم عليه من دون الله من إنس وجن، إن كنتم صادقين في دعواكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,39,'بل سارَعوا إلى التكذيب بالقرآن أول ما سمعوه، قبل أن يتدبروا آياته، وكفروا بما لم يحيطوا بعلمه من ذكر البعث والجزاء والجنة والنار وغير ذلك، ولم يأتهم بعدُ حقيقة ما وُعِدوا به في الكتاب. وكما كذَّب المشركون بوعيد الله كذَّبت الأمم التي خلت قبلهم، فانظر -أيها الرسول- كيف كانت عاقبة الظالمين؟ فقد أهلك الله بعضهم بالخسف، وبعضهم بالغرق، وبعضهم بغير ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,40,'ومِن قومك -أيها الرسول- مَن يصدِّق بالقرآن، ومنهم من لا يصدِّق به حتى يموت على ذلك ويبعث عليه، وربك أعلم بالمفسدين الذين لا يؤمنون به على وجه الظلم والعناد والفساد، فيجازيهم على فسادهم بأشد العذاب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,41,'وإن كذَّبك -أيها الرسول- هؤلاء المشركون فقل لهم: لي ديني وعملي، ولكم دينكم وعملكم، فأنتم لا تؤاخَذون بعملي، وأنا لا أؤاخَذ بعملكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,42,'ومِنَ الكفار مَن يسمعون كلامك الحق، وتلاوتك القرآن، ولكنهم لا يهتدون. أفأنت تَقْدر على إسماع الصم؟ فكذلك لا تقدر على هداية هؤلاء إلا أن يشاء الله هدايتهم؛ لأنهم صمٌّ عن سماع الحق، لا يعقلونه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,43,'ومِنَ الكفار مَن ينظر إليك وإلى أدلة نبوتك الصادقة، ولكنه لا يبصر ما آتاك الله من نور الإيمان، أفأنت -أيها الرسول- تقدر على أن تخلق للعمي أبصارًا يهتدون بها؟ فكذلك لا تقدر على هدايتهم إذا كانوا فاقدي البصيرة، وإنما ذلك كلُّه لله وحده.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,44,'إن الله لا يظلم الناس شيئًا بزيادة في سيئاتهم أو نقص من حسناتهم، ولكن الناس هم الذين يظلمون أنفسهم بالكفر والمعصية ومخالفة أمر الله ونهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,45,'ويوم يَحشر الله هؤلاء المشركين يوم البعث والحساب، كأنهم قبل ذلك لم يمكثوا في الحياة الدنيا إلا قدر ساعة من النهار، يعرف بعضهم بعضًا كحالهم في الدنيا، ثم انقطعت تلك المعرفة وانقضت تلك الساعة. قد خسر الذين كفروا وكذَّبوا بلقاء الله وثوابه وعقابه، وما كانوا موفَّقين لإصابة الرشد فيما فعلوا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,46,'وإمَّا نرينَّك -أيها الرسول- في حياتك بعض الذي نَعِدُهم من العقاب في الدنيا، أو نتوفينك قبل أن نريك ذلك فيهم، فإلينا وحدنا يرجع أمرهم في الحالتين، ثم الله شهيد على أفعالهم التي كانوا يفعلونها في الدنيا، لا يخفى عليه شيء منها، فيجازيهم بها جزاءهم الذي يستحقونه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,47,'ولكل أمة خَلَتْ قبلكم -أيها الناس- رسول أرسلتُه إليهم، كما أرسلت محمدًا إليكم يدعو إلى دين الله وطاعته، فإذا جاء رسولهم في الآخرة قُضِيَ حينئذ بينهم بالعدل، وهم لا يُظلمون مِن جزاء أعمالهم شيئًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,48,'ويقول المشركون من قومك -أيها الرسول-: متى قيام الساعة إن كنت أنت ومَن تبعك من الصادقين فيما تَعِدوننا به؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,49,'قل لهم -أيها الرسول-: لا أستطيع أن أدفع عن نفسي ضرًا، ولا أجلب لها نفعًا، إلا ما شاء الله أن يدفع عني مِن ضرٍّ أو يجلب لي من نفع. لكل قوم وقت لانقضاء مدتهم وأجلهم، إذا جاء وقت انقضاء أجلهم وفناء أعمارهم، فلا يستأخرون عنه ساعة فيُمْهلون، ولا يتقدم أجلهم عن الوقت المعلوم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,50,'قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أتاكم عذاب الله ليلا أو نهارًا، فأي شيء تستعجلون أيها المجرمون بنزول العذاب؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,51,'أبعدما وقع عذاب الله بكم -أيها المشركون- آمنتم في وقت لا ينفعكم فيه الإيمان؟ وقيل لكم حينئذ: آلآن تؤمنون به، وقد كنتم من قبل تستعجلون به؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,52,'ثم قيل للذين ظلموا أنفسهم بكفرهم بالله: تجرَّعوا عذاب الله الدائم لكم أبدًا، فهل تُعاقَبون إلا بما كنتم تعملون في حياتكم من معاصي الله؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,53,'ويستخبرك هؤلاء المشركون من قومك -أيها الرسول- عن العذاب يوم القيامة، أحقٌّ هو؟ قل لهم -أيها الرسول-: نعم وربي إنه لحق لا شك فيه، وما أنتم بمعجزين الله أن يبعثكم ويجازيكم، فأنتم في قبضته وسلطانه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,54,'ولو أن لكل نفس أشركت وكفرت بالله جميع ما في الأرض، وأمكنها أن تجعله فداء لها من ذلك العذاب لافتدت به، وأخفى الذين ظلموا حسرتهم حين أبصروا عذاب الله واقعا بهم جميعًا، وقضى الله عز وجل بينهم بالعدل، وهم لا يُظلَمون؛ لأن الله تعالى لا يعاقب أحدا إلا بذنبه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,55,'ألا إن كل ما في السموات وما في الأرض ملك لله تعالى، لا شيء من ذلك لأحد سواه. ألا إن لقاء الله تعالى وعذابه للمشركين كائن، ولكن أكثرهم لا يعلمون حقيقة ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,56,'إن الله هو المحيي والمميت لا يتعذَّر عليه إحياء الناس بعد موتهم، كما لا تعجزه إماتتهم إذا أراد ذلك، وهم إليه راجعون بعد موتهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,57,'يا أيها الناس قد جاءتكم موعظة من ربكم تذكِّركم عقاب الله وتخوفكم وعيده، وهي القرآن وما اشتمل عليه من الآيات والعظات لإصلاح أخلاقكم وأعمالكم، وفيه دواء لما في القلوب من الجهل والشرك وسائر الأمراض، ورشد لمن اتبعه من الخلق فينجيه من الهلاك، جعله سبحانه وتعالى نعمة ورحمة للمؤمنين، وخصَّهم بذلك؛ لأنهم المنتفعون بالإيمان، وأما الكافرون فهو عليهم عَمَى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,58,'قل -أيها الرسول- لجميع الناس: بفضل الله وبرحمته، وهو ما جاءهم من الله من الهدى ودين الحق وهو الإسلام، فبذلك فليفرحوا؛ فإن الإسلام الذي دعاهم الله إليه، والقرآن الذي أنزله على محمد صلى الله عليه وسلم، خير مما يجمعون من حطام الدنيا وما فيها من الزهرة الفانية الذاهبة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,59,'قل -أيها الرسول- لهؤلاء الجاحدين للوحي: أخبروني عن هذا الرزق الذي خلقه الله لكم من الحيوان والنبات والخيرات فحلَّلتم بعض ذلك لأنفسكم وحرَّمتم بعضه، قل لهم: آلله أذن لكم بذلك، أم تقولون على الله الباطل وتكذبون؟ وإنهم ليقولون على الله الباطل ويكذبون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,60,'وما ظنُّ هؤلاء الذين يتخرصون على الله الكذب يوم الحساب، فيضيفون إليه تحريم ما لم يحرمه عليهم من الأرزاق والأقوات، أن الله فاعل بهم يوم القيامة بكذبهم وفِرْيَتِهم عليه؟ أيحسبون أنه يصفح عنهم ويغفر لهم؟ إن الله لذو فضل على خلقه؛ بتركه معاجلة مَن افترى عليه الكذب بالعقوبة في الدنيا وإمهاله إياه، ولكن أكثر الناس لا يشكرون الله على تفضله عليهم بذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,61,'وما تكون -أيها الرسول- في أمر مِن أمورك وما تتلو من كتاب الله من آيات، وما يعمل أحد من هذه الأمة عملا من خير أو شر إلا كنا عليكم شهودًا مُطَّلِعين عليه، إذ تأخذون في ذلك، وتعملونه، فنحفظه عليكم ونجزيكم به، وما يغيب عن علم ربك -أيها الرسول- من زنة نملة صغيرة في الأرض ولا في السماء، ولا أصغر الأشياء ولا أكبرها، إلا في كتاب عند الله واضح جلي، أحاط به علمه وجرى به قلمه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,62,'ألا إن أولياء الله لا خوف عليهم في الآخرة من عقاب الله، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,63,'وصفات هؤلاء الأولياء، أنهم الذين صدَّقوا الله واتبعوا رسوله وما جاء به من عند الله، وكانوا يتقون الله بامتثال أوامره، واجتناب معاصيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,64,'لهؤلاء الأولياء البشارة من الله في الحياة الدنيا بما يسرُّهم، وفي الآخرة بالجنة، لا يخلف الله وعده ولا يغيِّره، ذلك هو الفوز العظيم؛ لأنه اشتمل على النجاة مِن كل محذور، والظَّفَر بكل مطلوب محبوب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,65,'ولا يحزنك -أيها الرسول- قول المشركين في ربهم وافتراؤهم عليه وإشراكهم معه الأوثان والأصنام؛ فإن الله تعالى هو المتفرد بالقوة الكاملة والقدرة التامة في الدنيا والآخرة، وهو السميع لأقوالهم، العليم بأفعالهم ونياتهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,66,'ألا إن لله كل مَن في السموات ومن في الأرض من الملائكة، والإنس، والجن وغير ذلك. وأي شيء يتَّبع مَن يدعو غير الله من الشركاء؟ ما يتَّبعون إلا الشك، وإن هم إلا يكذبون فيما ينسبونه إلى الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,67,'هو الذي جعل لكم -أيها الناس- الليل لتسكنوا فيه وتهدؤوا من عناء الحركة في طلب المعاش، وجعل لكم النهار؛ لتبصروا فيه، ولتسعَوْا لطلب رزقكم. إن في اختلاف الليل والنهار وحال أهلهما فيهما لَدلالةً وحججًا على أن الله وحده هو المستحق للعبادة، لقوم يسمعون هذه الحجج، ويتفكرون فيها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,68,'قال المشركون: اتخذ الله ولدًا، كقولهم: الملائكة بنات الله، أو المسيح ابن الله. تقدَّس الله عن ذلك كله وتنزَّه، هو الغني عن كل ما سواه، له كل ما في السموات والأرض، فكيف يكون له ولد ممن خلق وكل شيء مملوك له؟ وليس لديكم دليل على ما تفترونه من الكذب، أتقولون على الله ما لا تعلمون حقيقته وصحته؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,69,'قل: إن الذين يفترون على الله الكذب باتخاذ الولد وإضافة الشريك إليه، لا ينالون مطلوبهم في الدنيا ولا في الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,70,'إنما يتمتعون في الدنيا بكفرهم وكذبهم متاعًا قصيرًا، ثم إذا انقضى أجلهم فإلينا مصيرهم، ثم نذيقهم عذاب جهنم بسبب كفرهم بالله وتكذيبهم رسل الله، وجحدهم آياته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,71,'واقصص -أيها الرسول- على كفار "مكة" خبر نوح -عليه السلام- مع قومه حين قال لهم: إن كان عَظُمَ عليكم مقامي فيكم وتذكيري إياكم بحجج الله وبراهينه فعلى الله اعتمادي وبه ثقتي، فأعدُّوا أمركم، وادعوا شركاءكم، ثم لا تجعلوا أمركم عليكم مستترًا بل ظاهرًا منكشفًا، ثم اقضوا عليَّ بالعقوبة والسوء الذي في إمكانكم، ولا تمهلوني ساعة من نهار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,72,'فإن أعرضتم عن دعوتي فإنني لم أسألكم أجرًا؛ لأن ثوابي عند ربي وأجري عليه سبحانه، وحده لا شريك له، وأمرت أن أكون من المنقادين لحكمه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,73,'فكذب نوحًا قومُه فيما أخبرهم به عن الله، فنجَّيناه هو ومن معه في السفينة، وجعلناهم يَخْلُفون المكذبين في الأرض، وأغرقنا الذين جحدوا حججنا، فتأمل -أيها الرسول- كيف كان عاقبة القوم الذين أنذرهم رسولهم عذاب الله وبأسه؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,74,'ثم بعثنا من بعد نوح رسلا إلى أقوامهم (هودًا وصالحًا وإبراهيم ولوطًا وشعيبًا وغيرَهم) فجاء كل رسول قومه بالمعجزات الدالة على رسالته، وعلى صحة ما دعاهم إليه، فما كانوا ليصدِّقوا ويعملوا بما كذَّب به قوم نوح ومَن سبقهم من الأمم الخالية. وكما ختم الله على قلوب هؤلاء الأقوام فلم يؤمنوا، كذلك يختم على قلوب مَن شابههم ممن بعدهم من الذين تجاوزوا حدود الله، وخالفوا ما دعاهم إليه رسلهم من طاعته عقوبة لهم على معاصيهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,75,'ثم بعثنا مِن بعد أولئك الرسل موسى وهارون عليهما السلام إلى فرعون وأشراف قومه بالمعجزات الدالة على صدقهما، فاستكبروا عن قَبول الحق، وكانوا قومًا مشركين مجرمين مكذبين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,76,'فلما أتى فرعونَ وقومَه الحقُّ الذي جاء به موسى قالوا: إن الذي جاء به موسى من الآيات إنما هو سحر ظاهر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,77,'قال لهم موسى متعجبًا مِن قولهم: أتقولون للحق لما جاءكم: إنه سحر مبين؟ انظروا وَصْفَ ما جاءكم وما اشتمل عليه تجدوه الحق. ولا يفلح الساحرون، ولا يفوزون في الدنيا ولا في الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,78,'قال فرعون وملؤه لموسى: أجئتنا لتصرفنا عما وجدنا عليه آباءنا من عبادة غير الله، وتكون لكما أنت وهارون العظمة والسلطان في أرض "مصر"؟ وما نحن لكما بمقرِّين بأنكما رسولان أُرسلتما إلينا؛ لنعبد الله وحده لا شريك له.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,79,'وقال فرعون: جيئوني بكل ساحر متقن للسحر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,80,'فلما جاء السحرة فرعون قال لهم موسى: ألقوا على الأرض ما معكم من حبالكم وعصيِّكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,81,'فلما ألقَوا حبالهم وعصيَّهم قال لهم موسى: إنَّ الذي جئتم به وألقيتموه هو السحر، إن الله سيُذْهب ما جئتم به وسيُبطله، إن الله لا يصلح عمل مَن سعى في أرض الله بما يكرهه، وأفسد فيها بمعصيته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,82,'ويثبِّت الله الحق الذي جئتكم به من عنده فيُعليه على باطلكم بكلماته وأمره، ولو كره المجرمون أصحاب المعاصي مِن آل فرعون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,83,'فما آمن لموسى عليه السلام مع ما أتاهم به من الحجج والأدلة إلا ذرية من قومه من بني إسرائيل، وهم خائفون من فرعون وملئه أن يفتنوهم بالعذاب، فيصدُّوهم عن دينهم، وإن فرعون لَجبار مستكبر في الأرض، وإنه لمن المتجاوزين الحد في الكفر والفساد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,84,'وقال موسى: يا قومي إن صدقتم بالله -جلَّ وعلا- وامتثلتم شرعه فثقوا به، وسلِّموا لأمره، وعلى الله توكلوا إن كنتم مذعنين له بالطاعة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,85,'فقال قوم موسى له: على الله وحده لا شريك له اعتمدنا، وإليه فوَّضنا أمرنا، ربنا لا تنصرهم علينا فيكون ذلك فتنة لنا عن الدين، أو يُفتن الكفارُ بنصرهم، فيقولوا: لو كانوا على حق لما غُلبوا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,86,'ونجِّنا برحمتك من القوم الكافرين فرعون وملئه؛ لأنهم كانوا يأخذونهم بالأعمال الشاقة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,87,'وأوحينا إلى موسى وأخيه هارون أن اتخذا لقومكما بيوتًا في "مصر" تكون مساكن وملاجئ تعتصمون بها، واجعلوا بيوتكم أماكن تصلُّون فيها عند الخوف، وأدُّوا الصلاة المفروضة في أوقاتها. وبشِّر المؤمنين المطيعين لله بالنصر المؤزر، والثواب الجزيل منه سبحانه وتعالى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,88,'وقال موسى: ربنا إنك أعطيت فرعون وأشراف قومه زينة من متاع الدنيا؛ فلم يشكروا لك، وإنما استعانوا بها على الإضلال عن سبيلك، ربنا اطمس على أموالهم، فلا ينتفعوا بها، واختم على قلوبهم حتى لا تنشرح للإيمان، فلا يؤمنوا حتى يروا العذاب الشديد الموجع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,89,'قال الله تعالى لهما: قد أجيبت دعوتكما في فرعون وملئه وأموالهم -وكان موسى يدعو، وهارون يؤمِّن على دعائه، فمن هنا نسبت الدعوة إلى الاثنين- فاستقيما على دينكما، واستمرَّا على دعوتكما فرعون وقومه إلى توحيد الله وطاعته، ولا تسلكا طريق مَن لا يعلم حقيقة وعدي ووعيدي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,90,'وقطَعْنا ببني إسرائيل البحر حتى جاوزوه، فأتبعهم فرعون وجنوده ظلمًا وعدوانًا، فسلكوا البحر وراءهم، حتى إذا أحاط بفرعون الغرق قال: آمنتُ أنه لا إله إلا الذي آمنتْ به بنو إسرائيل، وأنا من الموحدين المستسلمين بالانقياد والطاعة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,91,'آلآن يا فرعون، وقد نزل بك الموت تقرُّ لله بالعبودية، وقد عصيته قبل نزول عذابه بك، وكنت من المفسدين الصادين عن سبيله!! فلا تنفعك التوبة ساعة الاحتضار ومشاهدة الموت والعذاب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,92,'فاليوم نجعلك على مرتفع من الأرض ببدنك، ينظر إليك من كذَّب بهلاكك؛ لتكون لمن بعدك من الناس عبرة يعتبرون بك. فإن كثيرًا من الناس عن حججنا وأدلتنا لَغافلون، لا يتفكرون فيها ولا يعتبرون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,93,'ولقد أنزلنا بني إسرائيل منزلا صالحًا مختارًا في بلاد "الشام" و"مصر"، ورزقناهم الرزق الحلال الطيب من خيرات الأرض المباركة، فما اختلفوا في أمر دينهم إلا مِن بعد ما جاءهم العلم الموجب لاجتماعهم وائتلافهم، ومن ذلك ما اشتملت عليه التوراة من الإخبار بنبوة محمد صلى الله عليه وسلم. إن ربك -أيها الرسول- يقضي بينهم يوم القيامة، ويَفْصِل فيما كانوا يختلفون فيه من أمرك، فيدخل المكذبين النار والمؤمنين الجنة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,94,'فإن كنت -أيها الرسول- في ريب من حقيقة ما أخبرناك به فاسأل الذين يقرؤون الكتاب من قبلك من أهل التوراة والإنجيل، فإن ذلك ثابت في كتبهم، لقد جاءك الحق اليقين من ربك بأنك رسول الله، وأن هؤلاء اليهود والنصارى يعلمون صحة ذلك، ويجدون صفتك في كتبهم، ولكنهم ينكرون ذلك مع علمهم به، فلا تكوننَّ من الشاكِّين في صحة ذلك وحقيقته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,95,'ولا تكونن -أيها الرسول- من الذين كذَّبوا بحجج الله وأدلته فتكون من الخاسرين الذين سخِطَ الله عليهم ونالوا عقابه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,96,'إن الذين حقَّت عليهم كلمة ربك -أيها الرسول- بطردهم من رحمته وعذابه لهم، لا يؤمنون بحجج الله، ولا يقرُّون بوحدانيته، ولا يعملون بشرعه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,97,'ولو جاءتهم كل موعظة وعبرة حتى يعاينوا العذاب الموجع، فحينئذ يؤمنون، ولا ينفعهم إيمانهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,98,'لم ينفع الإيمان أهل قرية آمنوا عند معاينة العذاب إلا أهل قرية يونس بن مَتَّى، فإنهم لـمَّا أيقنوا أن العذاب نازل بهم تابوا إلى الله تعالى توبة نصوحا، فلمَّا تبيَّن منهم الصدق في توبتهم كشف الله عنهم عذاب الخزي بعد أن اقترب منهم، وتركهم في الدنيا يستمتعون إلى وقت إنهاء آجالهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,99,'ولو شاء ربك -أيها الرسول- الإيمان لأهل الأرض كلهم لآمنوا جميعًا بما جئتهم به، ولكن له حكمة في ذلك؛ فإنه يهدي من يشاء ويضل من يشاء وَفْق حكمته، وليس في استطاعتك أن تُكْره الناس على الإيمان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,100,'وما كان لنفس أن تؤمن بالله إلا بإذنه وتوفيقه، فلا تُجهد نفسك في ذلك، فإن أمرهم إلى الله. ويجعل الله العذاب والخزي على الذين لا يعقلون أمره ونهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,101,'قل -أيها الرسول- لقومك: تفكروا واعتبروا بما في السموات والأرض من آيات الله البينات، ولكن الآيات والعبر والرسل المنذرة عباد الله عقابه، لا تنفع قومًا لا يؤمنون بشيء من ذلك؛ لإعراضهم وعنادهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,102,'فهل ينتظر هؤلاء إلا يومًا يعاينون فيه عذاب الله مثل أيام أسلافهم المكذبين الذين مَضَوا قبلهم؟ قل لهم -أيها الرسول-: فانتظروا عقاب الله إني معكم من المنتظرين عقابكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,103,'ثم ننجِّي رسلنا والذين آمنوا معهم، وكما نجينا أولئك ننجِّيك -أيها الرسول- ومن آمن بك تفضلا منَّا ورحمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,104,'قل -أيها الرسول- لهؤلاء الناس: إن كنتم في شك من صحة ديني الذي دعوتكم إليه، وهو الإسلام ومن ثباتي واستقامتي عليه، وترجون تحويلي عنه، فإني لا أعبد في حال من الأحوال أحدًا من الذين تعبدونهم مما اتخذتم من الأصنام والأوثان، ولكن أعبد الله وحده الذي يميتكم ويقبض أرواحكم، وأُمِرْت أن أكون من المصدِّقين به العاملين بشرعه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,105,'وأن أقم -أيها الرسول- نفسك على دين الإسلام مستقيمًا عليه غير مائل عنه إلى يهودية ولا نصرانية ولا عبادة غيره، ولا تكونن ممن يشرك في عبادة ربه الآلهة والأنداد، فتكون من الهالكين. وهذا وإن كان خطابًا للرسول صلى الله عليه وسلَّم فإنه موجَّه لعموم الأمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,106,'ولا تَدْعُ -أيها الرسول- من دون الله شيئًا من الأوثان والأصنام؛ لأنها لا تنفع ولا تضرُّ، فإن فعَلْت ذلك ودعوتها من دون الله فإنك إذًا من المشركين بالله، الظالمين لأنفسهم بالشرك والمعصية. وهذا وإن كان خطابًا للرسول صلى الله عليه وسلَّم فإنه موجَّه لعموم الأمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,107,'وإن يصبك الله -أيها الرسول- بشدة أو بلاء فلا كاشف لذلك إلا هو جلَّ وعلا وإن يُرِدْك برخاء أو نعمة لا يمنعه عنك أحد، يصيب الله عز وجل بالسراء والضراء من يشاء من عباده، وهو الغفور لذنوب مَن تاب، الرحيم بمن آمن به وأطاعه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,108,'قل -أيها الرسول- لهؤلاء الناس: قد جاءكم رسول الله بالقرآن الذي فيه بيان هدايتكم، فمن اهتدى بهدي الله فإنما ثمرة عمله راجعة إليه، ومن انحرف عن الحق وأصرَّ على الضلال فإنما ضلاله وضرره على نفسه، وما أنا موكَّل بكم حتى تكونوا مؤمنين، إنما أنا رسول مبلِّغ أبلِّغكم ما أُرْسِلْت به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),10,109,'واتبع -أيها الرسول- وحي الله الذي يوحيه إليك فاعمل به، واصبر على طاعة الله تعالى، وعن معصيته، وعلى أذى من آذاك في تبليغ رسالته، حتى يقضي الله فيهم وفيك أمره، وهو -عزَّ وجل- خير الحاكمين؛ فإن حكمه مشتمل على العدل التام.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/10/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=10) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,1,'(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,2,'وإنزال القرآن وبيان أحكامه وتفصيلها وإحكامها؛ لأجل أن لا تعبدوا إلا الله وحده لا شريك له. إنني لكم -أيها الناس- من عند الله نذير ينذركم عقابه، وبشير يبشِّركم بثوابه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,3,'واسألوه أن يغفر لكم ذنوبكم، ثم ارجعوا إليه نادمين يمتعْكم في دنياكم متاعًا حسنًا بالحياة الطيبة فيها، إلى أن يحين أجلكم، ويُعطِ كل ذي فضل من علم وعمل جزاء فضله كاملا لا نقص فيه، وإن تعرضوا عمَّا أدعوكم إليه فإني أخشى عليكم عذاب يوم شديد، وهو يوم القيامة. وهذا تهديد شديد لمن تولَّى عن أوامر الله تعالى وكذَّب رسله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,4,'إلى الله رجوعكم بعد موتكم جميعًا فاحذروا عقابه، وهو سبحانه قادر على بعثكم وحشركم وجزائكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,5,'إن هؤلاء المشركين يضمرون في صدورهم الكفر؛ ظنًا منهم أنه يخفى على الله ما تضمره نفوسهم، ألا يعلمون حين يغطُّون أجسادهم بثيابهم أن الله لا يخفى عليه سِرُّهم وعلانيتهم؟ إنه عليم بكل ما تُكِنُّه صدورهم من النيات والضمائر والسرائر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,6,'لقد تكفَّل الله برزق جميع ما دبَّ على وجه الأرض، تفضلا منه، ويعلم مكان استقراره في حياته وبعد موته، ويعلم الموضع الذي يموت فيه، كل ذلك مكتوب في كتاب عند الله مبين عن جميع ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,7,'وهو الذي خلق السماوات والأرض وما فيهن في ستة أيام، وكان عرشه على الماء قبل ذلك؛ ليختبركم أيكم أحسن له طاعةً وعملا وهو ما كان خالصًا لله موافقًا لما كان عليه رسول الله صلى الله عليه وسلم. ولئن قلت -أيها الرسول- لهؤلاء المشركين من قومك: إنكم مبعوثون أحياءً بعد موتكم، لسارعوا إلى التكذيب وقالوا: ما هذا القرآن الذي تتلوه علينا إلا سحر بيِّن.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,8,'ولئن أخَّرنا عن هؤلاء المشركين العذاب إلى أجل معلوم فاستبطؤوه، ليقولُنَّ استهزاء وتكذيبًا: أي شيء يمنع هذا العذاب من الوقوع إن كان حقًا؟ ألا يوم يأتيهم ذلك العذاب لا يستطيع أن يصرفه عنهم صارف، ولا يدفعه دافع، وأحاط بهم من كل جانب عذاب ما كانوا يستهزئون به قبل وقوعه بهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,9,'ولئن أعطينا الإنسان مِنَّا نعمة من صحة وأمن وغيرهما، ثم سلبناها منه، إنه لَشديد اليأس من رحمة الله، جَحود بالنعم التي أنعم الله بها عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,10,'ولئن بسطنا للإنسان في دنياه ووسَّعنا عليه في رزقه بعد ضيق من العيش، ليقولَنَّ عند ذلك: ذهب الضيق عني وزالت الشدائد، إنه لبَطِر بالنعم، مبالغ في الفخر والتعالي على الناس.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,11,'لكن الذين صبروا على ما أصابهم من الضراء إيمانًا بالله واحتسابًا للأجر عنده، وعملوا الصالحات شكرا لله على نعمه، هؤلاء لهم مغفرة لذنوبهم وأجر كبير في الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,12,'فلعلك -أيها الرسول لعظم ما تراه منهم من الكفر والتكذيب- تارك بعض ما يوحى إليك مما أنزله الله عليك وأمرك بتبليغه، وضائق به صدرك؛ خشية أن يطلبوا منك بعض المطالب على وجه التعنت، كأن يقولوا: لولا أُنزل عليه مال كثير، أو جاء معه ملك يصدقه في رسالته، فبلغهم ما أوحيته إليك؛ فإنه ليس عليك إلا الإنذار بما أُوحي إليك. والله على كل شيء حفيظ يدَبِّر جميع شؤون خلقه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,13,'بل أيقول هؤلاء المشركون من أهل "مكة": إن محمدًا قد افترى هذا القرآن؟ قل لهم: إن كان الأمر كما تزعمون فأتوا بعشر سور مثله مفتريات، وادعوا من استطعتم من جميع خلق الله ليساعدوكم على الإتيان بهذه السور العشر، إن كنتم صادقين في دعواكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,14,'فإن لم يستجب هؤلاء المشركون لكم -أيها الرسول ومَن آمن معك- لما تدعونهم إليه؛ لِعَجْز الجميع عن ذلك، فاعلموا أن هذا القرآن إنما أنزله الله على رسوله بعلمه وليس من قول البشر، واعلموا أن لا إله يُعبد بحق إلا الله، فهل أنتم -بعد قيام هذه الحجة عليكم- مسلمون منقادون لله ورسوله؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,15,'من كان يريد بعمله الحياة الدنيا ومُتَعها نعطهم ما قُسِم لهم من ثواب أعمالهم في الحياة الدنيا كاملا غير منقوص.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,16,'أولئك ليس لهم في الآخرة إلا نار جهنم يقاسون حرَّها، وذهب عنهم نَفْع ما عملوه، وكان عملهم باطلا لأنه لم يكن لوجه الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,17,'أفمَن كان على حجة وبصيرة من ربه فيما يؤمن به، ويدعو إليه بالوحي الذي أنزل الله فيه هذه البينة، ويتلوها برهان آخر شاهد منه، وهو جبريل أو محمد عليهما السلام، ويؤيد ذلك برهان ثالث من قبل القرآن، وهو التوراة -الكتاب الذي أنزل على موسى إمامًا ورحمة لمن آمن به-، كمن كان همه الحياة الفانية بزينتها؟ أولئك يصدِّقون بهذا القرآن ويعملون بأحكامه، ومن يكفر بهذا القرآن من الذين تحزَّبوا على رسول الله صلى الله عليه وسلم فجزاؤه النار، يَرِدُها لا محالة، فلا تك -أيها الرسول- في شك من أمر القرآن وكونه من عند الله تعالى بعد ما شهدت بذلك الأدلة والحجج، واعلم أن هذا الدين هو الحق من ربك، ولكن أكثر الناس لا يصدِّقون ولا يعملون بما أُمروا به. وهذا توجيه عام لأمة محمد صلى الله عليه وسلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,18,'ولا أحد أظلم ممن اختلق على الله كذبًا، أولئك سيعرضون على ربهم يوم القيامة؛ ليحاسبهم على أعمالهم، ويقول الأشهاد من الملائكة والنبيين وغيرهم: هؤلاء الذين كذبوا على ربهم في الدنيا قد سخط الله عليهم، ولعنهم لعنة لا تنقطع؛ لأن ظلمهم صار وصفًا ملازمًا لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,19,'هؤلاء الظالمون الذين يمنعون الناس عن سبيل الله الموصلة إلى عبادته، ويريدون أن تكون هذه السبيل عوجاء بموافقتها لأهوائهم، وهم كافرون بالآخرة لا يؤمنون ببعث ولا جزاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,20,'أولئك الكافرون لم يكونوا ليفوتوا الله في الدنيا هربًا، وما كان لهم مِن أنصار يمنعونهم من عقابه. يضاعَفُ لهم العذاب في جهنم؛ لأنهم كانوا لا يستطيعون أن يسمعوا القرآن سماع منتفع، أو يبصروا آيات الله في هذا الكون إبصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,21,'أولئك الذين خسروا أنفسهم بافترائهم على الله، وذهب عنهم ما كانوا يفترون من الآلهة التي يدَّعون أنها تشفع لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,22,'حقًا أنهم في الآخرة أخسر الناس صفقة؛ لأنهم استبدلوا الدركات بالدرجات، فكانوا في جهنم، وذلك هو الخسران المبين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,23,'إن الذين صدَّقوا الله ورسوله وعملوا الأعمال الصالحة، وخضعوا لله في كل ما أُمروا به ونُهوا عنه، أولئك هم أهل الجنة، لا يموتون فيها، ولا يَخْرجون منها أبدًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,24,'مثل فريقَي الكفر والإيمان كمثل الأعمى الذي لا يرى والأصم الذي لا يسمع والبصير والسميع: ففريق الكفر لا يبصر الحق فيتبعه، ولا يسمع داعي الله فيهتدي به، أما فريق الإيمان فقد أبصر حجج الله وسمع داعي الله فأجابه، هل يستوي هذان الفريقان؟ أفلا تعتبرون وتتفكرون؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,25,'ولقد أرسلنا نوحًا إلى قومه فقال لهم: إني نذير لكم من عذاب الله، مبيِّن لكم ما أُرسلت به إليكم من أمر الله ونهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,26,'آمركم ألا تعبدوا إلا الله، إني أخاف عليكم -إن لم تفردوا الله وحده بالعبادة- عذاب يوم موجع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,27,'فقال رؤساء الكفر من قومه: إنك لست بمَلَك ولكنك بشر، فكيف أُوحي إليك مِن دوننا؟ وما نراك اتبعك إلا الذين هم أسافلنا وإنما اتبعوك من غير تفكر ولا رويَّة، وما نرى لكم علينا من فضل في رزق ولا مال لـمَّا دخلتم في دينكم هذا، بل نعتقد أنكم كاذبون فيما تدَّعون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,28,'قال نوح: يا قومي أرأيتم إن كنتُ على حجة ظاهرة من ربي فيما جئتكم به تبيِّن لكم أنني على الحق من عنده، وآتاني رحمة من عنده، وهي النبوة والرسالة فأخفاها عليكم بسبب جهلكم وغروركم، فهل يصح أن نُلْزمكم إياها بالإكراه وأنتم جاحدون بها؟ لا نفعل ذلك، ولكن نَكِل أمركم إلى الله حتى يقضي في أمركم ما يشاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,29,'قال نوح عليه السلام لقومه: يا قوم لا أسألكم على دعوتكم لتوحيد الله وإخلاص العبادة له مالاً تؤدونه إليَّ بعد إيمانكم، ولكن ثواب نصحي لكم على الله وحده، وليس من شأني أن أطرد المؤمنين، فإنهم ملاقو ربهم يوم القيامة، ولكني أراكم قومًا تجهلون؛ إذ تأمرونني بطرد أولياء الله وإبعادهم عني.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,30,'ويا قوم مَن يمنعني من الله إن عاقبني على طردي المؤمنين؟ أفلا تتدبرون الأمور فتعلموا ما هو الأنفع لكم والأصلح؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,31,'ولا أقول لكم: إني أملك التصرف في خزائن الله، ولا أعلم الغيب، ولست بمَلَك من الملائكة، ولا أقول لهؤلاء الذين تحتقرون من ضعفاء المؤمنين: لن يؤتيكم الله ثوابًا على أعمالكم، فالله وحده أعلم بما في صدورهم وقلوبهم، ولئن فعلتُ ذلك إني إذًا لمن الظالمين لأنفسهم ولغيرهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,32,'قالوا: يا نوح قد حاججتنا فأكثرت جدالنا، فأتنا بما تعدنا من العذاب إن كنت من الصادقين في دعواك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,33,'قال نوح لقومه: إن الله وحده هو الذي يأتيكم بالعذاب إذا شاء، ولستم بفائتيه إذا أراد أن يعذبكم؛ لأنه سبحانه لا يعجزه شيء في الأرض ولا في السماء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,34,'ولا ينفعكم نصحي واجتهادي في دعوتكم للإيمان، إن كان الله يريد أن يضلَّكم ويهلككم، هو سبحانه مالككم، وإليه تُرجَعون في الآخرة للحساب والجزاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,35,'بل أيقول هؤلاء المشركون من قوم نوح: افترى نوح هذا القول؟ قل لهم: إن كنتُ قد افتريتُ ذلك على الله فعليَّ وحدي إثم ذلك، وإذا كنتُ صادقًا فأنتم المجرمون الآثمون، وأنا بريء مِن كفركم وتكذيبكم وإجرامكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,36,'وأوحى الله سبحانه وتعالى إلى نوح -عليه السلام- لـمَّا حق على قومه العذاب، أنه لن يؤمن بالله إلا مَن قد آمن مِن قبل، فلا تحزن يا نوح على ما كانوا يفعلون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,37,'واصنع السفينة بمرأى منَّا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكلاءتنا، ولا تطلب مني إمهال هؤلاء الذين ظلموا أنفسهم من قومك بكفرهم، فإنهم مغرقون بالطوفان. وفي الآية إثبات صفة العين لله تعالى على ما يليق به سبحانه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,38,'ويصنع نوح السفينة، وكلَّما مر عليه جماعة من كبراء قومه سخروا منه، قال لهم نوح: إن تسخروا منا اليوم لجهلكم بصدق وعد الله، فإنا نسخر منكم غدًا عند الغرق كما تسخرون منا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,39,'فسوف تعلمون إذا جاء أمر الله بذلك: من الذي يأتيه في الدنيا عذاب الله الذي يُهينه، وينزل به في الآخرة عذاب دائم لا انقطاع له؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,40,'حتى إذا جاء أمرنا بإهلاكهم كما وَعدْنا نوحًا بذلك، ونبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، قلنا لنوح: احمل في السفينة من كل نوع من أنواع الحيوانات ذكرًا وأنثى، واحمل فيها أهل بيتك، إلا مَن سبق عليهم القول ممن لم يؤمن بالله كابنه وامرأته، واحمل فيها من آمن معك من قومك، وما آمن معه إلا قليل مع طول المدة والمقام فيهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,41,'وقال نوح لمن آمن معه: اركبوا في السفينة، باسم الله يكون جريها على وجه الماء، وباسم الله يكون منتهى سيرها ورُسوُّها. إن ربي لَغفور ذنوب من تاب وأناب إليه من عباده، رحيم بهم أن يعذبهم بعد التوبة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,42,'وهي تجري بهم في موج يعلو ويرتفع حتى يصير كالجبال في علوها، ونادى نوح ابنه -وكان في مكانٍ عَزَل فيه نفسه عن المؤمنين- فقال له: يا بني اركب معنا في السفينة، ولا تكن مع الكافرين بالله فتغرق.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,43,'قال ابن نوح: سألجأ إلى جبل أتحصَّن به من الماء، فيمنعني من الغرق، فأجابه نوح: لا مانع اليوم من أمر الله وقضائه الذي قد نزل بالخلق من الغرق والهلاك إلا مَن رحمه الله تعالى، فآمِنْ واركب في السفينة معنا، وحال الموج المرتفع بين نوح وابنه، فكان من المغرقين الهالكين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,44,'وقال الله للأرض -بعد هلاك قوم نوح -: يا أرض اشربي ماءك، ويا سماء أمسكي عن المطر، ونقص الماء ونضب، وقُضي أمر الله بهلاك قوم نوح، ورست السفينة على جبل الجوديِّ، وقيل: هلاكًا وبعدًا للقوم الظالمين الذين تجاوزوا حدود الله، ولم يؤمنوا به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,45,'ونادى نوح ربه فقال: رب إنك وعَدْتني أن تنجيني وأهلي من الغرق والهلاك، وإن ابني هذا من أهلي، وإن وعدك الحق الذي لا خُلْف فيه، وأنت أحكم الحاكمين وأعدلهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,46,'قال الله: يا نوح إن ابنك الذي هلك ليس من أهلك الذين وعدتك أن أنجيهم؛ وذلك بسبب كفره، وعمله عملا غير صالح، وإني أنهاك أن تسألني أمرًا لا علم لك به، إني أعظك لئلا تكون من الجاهلين في مسألتك إياي عن ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,47,'قال نوح: يا رب إني أعتصم وأستجير بك أن أسألك ما ليس لي به علم، وإن لم تغفر لي ذنبي، وترحمني برحمتك، أكن من الذين غَبَنوا أنفسهم حظوظها وهلكوا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,48,'قال الله: يا نوح اهبط من السفينة إلى الأرض بأمن وسلامة منَّا وبركات عليك وعلى أمم ممن معك. وهناك أمم وجماعات من أهل الشقاء سنمتعهم في الحياة الدنيا، إلى أن يبلغوا آجالهم، ثم ينالهم منا العذاب الموجع يوم القيامة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,49,'تلك القصة التي قصصناها عليك -أيها الرسول- عن نوح وقومه هي من أخبار الغيب السالفة، نوحيها إليك، ما كنت تعلمها أنت ولا قومك مِن قبل هذا البيان، فاصبر على تكذيب قومك وإيذائهم لك، كما صبر الأنبياء من قبل، إن العاقبة الطيبة في الدنيا والآخرة للمتقين الذين يخشون الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,50,'وأرسلنا إلى عاد أخاهم هودًا، قال لهم: يا قوم اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، فما أنتم إلا كاذبون في إشراككم بالله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,51,'يا قوم لا أسألكم على ما أدعوكم إليه من إخلاص العبادة لله وترك عبادة الأوثان أجرًا، ما أجري على دعوتي لكم إلا على الله الذي خلقني، أفلا تعقلون فتميِّزوا بين الحق والباطل؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,52,'ويا قوم اطلبوا مغفرة الله والإيمان به، ثم توبوا إليه من ذنوبكم، فإنكم إن فعلتم ذلك يرسل المطر عليكم متتابعًا كثيرًا، فتكثر خيراتكم، ويزدكم قوة إلى قوتكم بكثرة ذرياتكم وتتابع النِّعم عليكم، ولا تُعرضوا عما دعوتكم إليه مصرِّين على إجرامكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,53,'قالوا: يا هود ما جئتنا بحجة واضحة على صحة ما تدعونا إليه، وما نحن بتاركي آلهتنا التي نعبدها من أجل قولك، وما نحن بمصدِّقين لك فيما تدَّعيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,54,'ما نقول إلا أن بعض آلهتنا أصابك بجنون بسبب نهيك عن عبادتها. قال لهم: إني أُشهد الله على ما أقول، وأُشهدكم على أنني بريء مما تشركون، مِن دون الله من الأنداد والأصنام، فانظروا واجتهدوا أنتم ومَن زعمتم من آلهتكم في إلحاق الضرر بي، ثم لا تؤخروا ذلك طرفة عين؛ ذلك أن هودًا واثق كل الوثوق أنه لا يصيبه منهم ولا من آلهتهم أذى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,55,'ما نقول إلا أن بعض آلهتنا أصابك بجنون بسبب نهيك عن عبادتها. قال لهم: إني أُشهد الله على ما أقول، وأُشهدكم على أنني بريء مما تشركون، مِن دون الله من الأنداد والأصنام، فانظروا واجتهدوا أنتم ومَن زعمتم من آلهتكم في إلحاق الضرر بي، ثم لا تؤخروا ذلك طرفة عين؛ ذلك أن هودًا واثق كل الوثوق أنه لا يصيبه منهم ولا من آلهتهم أذى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,56,'إني توكلت على الله ربي وربكم مالك كل شيء والمتصرف فيه، فلا يصيبني شيء إلا بأمره، وهو القادر على كل شيء، فليس من شيء يدِبُّ على هذه الأرض إلا والله مالكه، وهو في سلطانه وتصرفه. إن ربي على صراط مستقيم، أي عدل في قضائه وشرعه وأمره. يجازي المحسن بإحسانه والمسيء بإساءته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,57,'فإن تُعرضوا عما أدعوكم إليه من توحيد الله وإخلاص العبادة له فقد أبلغتكم رسالة ربي إليكم، وقامت عليكم الحجة، وحيث لم تؤمنوا بالله فسيهلككم ويأتي بقوم آخرين يخلفونكم في دياركم وأموالكم، ويخلصون لله العبادة، ولا تضرونه شيئًا، إن ربي على كل شيء حفيظ، فهو الذي يحفظني من أن تنالوني بسوء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,58,'ولما جاء أمرنا بعذاب قوم هود نجَّينا منه هودًا والمؤمنين بفضل منَّا عليهم ورحمة، ونجَّيناهم من عذاب شديد أحله الله بعادٍ فأصبحوا لا يُرى إلا مساكنُهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,59,'وتلك عاد كفروا بآيات الله وعصَوا رسله، وأطاعوا أمر كل مستكبر على الله لا يقبل الحق ولا يُذْعن له.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,60,'وأُتبعوا في هذه الدنيا لعنة من الله وسخطًا منه يوم القيامة. ألا إن عادًا جحدوا ربهم وكذَّبوا رسله. ألا بُعْدًا وهلاكًا لعاد قوم هود؛ بسبب شركهم وكفرهم نعمة ربهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,61,'وأرسلنا إلى ثمود أخاهم صالحًا، فقال لهم: يا قوم اعبدوا الله وحده ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، هو الذي بدأ خَلْقكم من الأرض بخلق أبيكم آدم منها، وجعلكم عُمَّارا لها، فاسألوه أن يغفر لكم ذنوبكم، وارجعوا إليه بالتوبة النصوح. إن ربي قريب لمن أخلص له العبادة، ورغب إليه في التوبة، مجيب له إذا دعاه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,62,'قالت ثمود لنبيِّهم صالح: لقد كنا نرجو أن تكون فينا سيدًا مطاعًا قبل هذا القول الذي قلته لنا، أتنهانا أن نعبد الآلهة التي كان يعبدها آباؤنا؟ وإننا لفي شكٍّ مريب مِن دعوتك لنا إلى عبادة الله وحده.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,63,'قال صالح لقومه: يا قوم أخبروني إن كنت على برهان من الله وآتاني منه النبوة والحكمة، فمن الذي يدفع عني عقاب الله تعالى إن عصيته فلم أبلِّغ الرسالة وأنصحْ لكم؟ فما تزيدونني غير تضليل وإبعاد عن الخير.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,64,'ويا قوم هذه ناقة الله جعلها لكم حجة وعلامة تدلُّ على صدقي فيما أدعوكم إليه، فاتركوها تأكل في أرض الله فليس عليكم رزقها، ولا تمسُّوها بعَقْر، فإنكم إن فعلتم ذلك يأخذكم من الله عذاب قريب من عَقْرها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,65,'فكذَّبوه ونحروا الناقة، فقال لهم صالح: استمتعوا بحياتكم في بلدكم ثلاثة أيام، فإن العذاب نازل بكم بعدها، وذلك وَعْدٌ من الله غير مكذوب، لا بد من وقوعه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,66,'فلما جاء أمرنا بهلاك ثمود نجينا صالحًا والذين آمنوا معه من الهلاك برحمة منا، ونجيناهم من هوان ذلك اليوم وذلَّته. إن ربك -أيها الرسول- هو القوي العزيز، ومِن قوته وعزته أن أهلك الأمم الطاغية، ونجَّى الرسل وأتباعهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,67,'وأخذت الصيحة القوية ثمود الظالمين، فأصبحوا في ديارهم موتى هامدين ساقطين على وجوههم لا حِرَاك لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,68,'كأنهم في سرعة زوالهم وفنائهم لم يعيشوا فيها. ألا إن ثمود جحدوا بآيات ربهم وحججه. ألا بُعْدًا لثمود وطردًا لهم من رحمة الله، فما أشقاهم وأذلَّهم!!','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,69,'ولقد جاءت الملائكة إبراهيم يبشرونه هو وزوجته بإسحاق، ويعقوبَ بعده، فقالوا: سلامًا، قال ردًّا على تحيتهم: سلام، فذهب سريعًا وجاءهم بعجل سمين مشويٍّ ليأكلوا منه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,70,'فلما رأى إبراهيم أيديهم لا تَصِل إلى العجل الذي أتاهم به ولا يأكلون منه، أنكر ذلك منهم، وأحس في نفسه خيفة وأضمرها، قالت الملائكة -لما رأت ما بإبراهيم من الخوف-: لا تَخَفْ إنا ملائكة ربك أُرسلنا إلى قوم لوط لإهلاكهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,71,'وامرأة إبراهيم -سارة- كانت قائمة من وراء الستر تسمع الكلام، فضحكت تعجبًا مما سمعت، فبشرناها على ألسنة الملائكة بأنها ستلد مِن زوجها إبراهيم ولدًا يسمى إسحاق، وسيعيش ولدها، وسيكون لها بعد إسحاق حفيد منه، وهو يعقوب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,72,'قالت سارة لما بُشِّرت بإسحاق متعجبة: يا ويلتا كيف يكون لي ولد وأنا عجوز، وهذا زوجي في حال الشيخوخة والكبر؟ إن إنجاب الولد مِن مثلي ومثل زوجي مع كبر السن لَشيء عجيب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,73,'قالت الرسل لها: أتعجبين من أمر الله وقضائه؟ رحمة الله وبركاته عليكم معشر أهل بيت النبوة. إنه سبحانه وتعالى حميد الصفات والأفعال، ذو مَجْد وعظمة فيها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,74,'فلما ذهب عن إبراهيم الخوف الذي انتابه لعدم أكل الضيوف الطعام، وجاءته البشرى بإسحاق ويعقوب، ظلَّ يجادل رسلنا فيما أرسلناهم به من عقاب قوم لوط وإهلاكهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,75,'إن إبراهيم كثير الحلم لا يحب المعاجلة بالعقاب، كثير التضرع إلى الله والدعاء له، تائب يرجع إلى الله في أموره كلها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,76,'قالت رسل الله: يا إبراهيم أعرض عن هذا الجدال في أمر قوم لوط والتماس الرحمة لهم؛ فإنه قد حق عليهم العذاب، وجاء أمر ربك الذي قدَّره عليهم بهلاكهم، وإنهم نازل بهم عذاب من الله غير مصروف عنهم ولا مدفوع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,77,'ولما جاءت ملائكتنا لوطًا ساءه مجيئهم واغتمَّ لذلك؛ وذلك لأنه لم يكن يعلم أنهم رسل الله، فخاف عليهم من قومه، وقال: هذا يوم بلاء وشدة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,78,'وجاء قومُ لوط يسرعون المشي إليه لطلب الفاحشة، وكانوا مِن قبل مجيئهم يأتون الرجال شهوة دون النساء، فقال لوط لقومه: هؤلاء بناتي تَزَوَّجوهن فهنَّ أطهر لكم مما تريدون، وسماهن بناته؛ لأن نبي الأمة بمنزلة الأب لهم، فاخشوا الله واحذروا عقابه، ولا تفضحوني بالاعتداء على ضيفي، أليس منكم رجل ذو رشد، ينهى من أراد ركوب الفاحشة، فيحول بينهم وبين ذلك؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,79,'قال قوم لوط له: لقد علمتَ من قبلُ أنه ليس لنا في النساء من حاجة أو رغبة، وإنك لتعلم ما نريد، أي لا نريد إلا الرجال ولا رغبة لنا في نكاح النساء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,80,'قال لهم حين أبوا إلا فعل الفاحشة: لو أن لي بكم قوة وأنصارًا معي، أو أركَن إلى عشيرة تمنعني منكم، لَحُلْتُ بينكم وبين ما تريدون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,81,'قالت الملائكة: يا لوط إنَّا رسل ربك أَرْسَلَنا لإهلاك قومك، وإنهم لن يصلوا إليك، فاخرج من هذه القرية أنت وأهلك ببقية من الليل، ولا يلتفت منكم أحد وراءه؛ لئلا يرى العذاب فيصيبه، لكنَّ امرأتك التي خانتك بالكفر والنفاق سيصيبها ما أصاب قومك من الهلاك، إن موعد هلاكهم الصبح، وهو موعد قريب الحلول.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,82,'فلما جاء أمرنا بنزول العذاب بهم جعلنا عالي قريتهم التي كانوا يعيشون فيها سافلها فقلبناها، وأمطرنا عليهم حجارة من طين متصلِّب متين، قد صُفَّ بعضها إلى بعض متتابعة، معلَّمة عند الله بعلامة معروفة لا تشاكِل حجارة الأرض، وما هذه الحجارة التي أمطرها الله على قوم لوط من كفار قريش ببعيد أن يُمْطَروا بمثلها. وفي هذا تهديد لكل عاص متمرِّد على الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,83,'فلما جاء أمرنا بنزول العذاب بهم جعلنا عالي قريتهم التي كانوا يعيشون فيها سافلها فقلبناها، وأمطرنا عليهم حجارة من طين متصلِّب متين، قد صُفَّ بعضها إلى بعض متتابعة، معلَّمة عند الله بعلامة معروفة لا تشاكِل حجارة الأرض، وما هذه الحجارة التي أمطرها الله على قوم لوط من كفار قريش ببعيد أن يُمْطَروا بمثلها. وفي هذا تهديد لكل عاص متمرِّد على الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,84,'وأرسلنا إلى "مدين" أخاهم شعيبًا، فقال: يا قوم اعبدوا الله وحده، ليس لكم مِن إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، ولا تنقصوا الناس حقوقهم في مكاييلهم وموازينهم، إني أراكم في سَعَة عيش، وإني أخاف عليكم -بسبب إنقاص المكيال والميزان- عذاب يوم يحيط بكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,85,'ويا قوم أتمُّوا المكيال والميزان بالعدل، ولا تُنْقِصوا الناس حقهم في عموم أشيائهم، ولا تسيروا في الأرض تعملون فيها بمعاصي الله ونشر الفساد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,86,'إن ما يبقى لكم بعد إيفاء الكيل والميزان من الربح الحلال خير لكم ممَّا تأخذونه بالتطفيف ونحوه من الكسب الحرام، إن كنتم تؤمنون بالله حقا، فامتثلوا أمره، وما أنا عليكم برقيب أحصي عليكم أعمالكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,87,'قالوا: يا شعيب أهذه الصلاة التي تداوم عليها تأمرك بأن نترك ما يعبده آباؤنا من الأصنام والأوثان، أو أن نمتنع عن التصرف في كسب أموالنا بما نستطيع من احتيال ومكر؟ وقالوا -استهزاءً به-: إنك لأنت الحليم الرشيد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,88,'قال شعيب: يا قوم أرأيتم إن كنت على طريق واضح من ربي فيما أدعوكم إليه من إخلاص العبادة له، وفيما أنهاكم عنه من إفساد المال، ورزقني منه رزقًا واسعًا حلالا طيبًا؟ وما أريد أن أخالفكم فأرتكب أمرًا نهيتكم عنه، وما أريد فيما آمركم به وأنهاكم عنه إلا إصلاحكم قَدْر طاقتي واستطاعتي، وما توفيقي -في إصابة الحق ومحاولة إصلاحكم- إلا بالله، على الله وحده توكلت وإليه أرجع بالتوبة والإنابة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,89,'ويا قوم لا تحملنَّكم عداوتي وبغضي وفراق الدين الذي أنا عليه على العناد والإصرار على ما أنتم عليه من الكفر بالله، فيصيبكم مثلُ ما أصاب قوم نوح أو قوم هود أو قوم صالح من الهلاك، وما قوم لوط وما حلَّ بهم من العذاب ببعيدين عنكم لا في الدار ولا في الزمان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,90,'واطلبوا من ربِّكم المغفرة لذنوبكم، ثم ارجعوا إلى طاعته واستمروا عليها. إن ربِّي رحيم كثير المودة والمحبة لمن تاب إليه وأناب، يرحمه ويقبل توبته. وفي الآية إثبات صفة الرحمة والمودة لله تعالى، كما يليق به سبحانه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,91,'قالوا: يا شعيب ما نفقه كثيرًا مما تقول، وإننا لَنراك فينا ضعيفًا لست من الكبراء ولا من الرؤساء، ولولا مراعاة عشيرتك لقتلناك رَجْما بالحجارة -وكان رهطه من أهل ملتهم-، وليس لك قَدْر واحترام في نفوسنا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,92,'قال: يا قوم أعشيرتي أعزُّ وأكرم عليكم من الله؟ ونبذتم أمر ربكم فجعلتموه خلف ظهوركم، لا تأتمرون به ولا تنتهون بنهيه، إن ربي بما تعملون محيط، لا يخفى عليه من أعمالكم مثقال ذرة، وسيجازيكم عليها عاجلا وآجلا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,93,'ويا قوم اعملوا كل ما تستطيعون على طريقتكم وحالتكم، إني عامل مثابر على طريقتي وما وهبني ربي مِن دعوتكم إلى التوحيد، سوف تعلمون مَن منا يأتيه عذاب يذلُّه، ومَن منا كاذب في قوله، أنا أم أنتم؟ وانتظروا ما سيحل بكم إني معكم من المنتظرين. وهذا تهديد شديد لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,94,'ولما جاء أمرنا بإهلاك قوم شعيب نجَّينا رسولنا شعيبًا والذين آمنوا معه برحمة منا، وأخذت الذين ظلموا الصيحة من السماء، فأهلكتهم، فأصبحوا في ديارهم باركين على رُكَبهم ميتين لا حِرَاك بهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,95,'كأن لم يقيموا في ديارهم وقتًا من الأوقات. ألا بُعدًا لـ "مدين" -إذ أهلكها الله وأخزاها- كما بَعِدت ثمود، فقد اشتركت هاتان القبيلتان في البعد والهلاك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,96,'ولقد أرسلنا موسى بأدلتنا على توحيدنا وحجة تبين لمن عاينها وتأملها -بقلب صحيح- أنها تدل على وحدانية الله، وكَذِبِ كلِّ من ادَّعى الربوبية دونه سبحانه وتعالى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,97,'أرسلنا موسى إلى فرعون وأكابر أتباعه وأشراف قومه، فكفر فرعون وأمر قومه أن يتبعوه، فأطاعوه، وخالفوا أمر موسى، وليس في أمر فرعون رشد ولا هدى، وإنما هو جهل وضلال وكفر وعناد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,98,'يَقْدُم فرعون قومه يوم القيامة حتى يدخلهم النار، وقبُح المدخل الذي يدخلونه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,99,'وأتبعهم الله في هذه الدنيا مع العذاب الذي عجَّله لهم فيها من الغرق في البحر لعنةً، ويوم القيامة كذلك لعنة أخرى بإدخالهم النار، وبئس ما اجتمع لهم وترادَف عليهم من عذاب الله، ولعنة الدنيا والآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,100,'ذلك الذي ذكرناه لك -أيها الرسول- من أخبار القرى التي أهلكنا أهلها نخبرك به، ومن تلك القرى ما له آثار باقية، ومنها ما قد مُحِيَتْ آثاره، فلم يَبْق منه شيء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,101,'وما كان إهلاكهم بغير سبب وذنب يستحقونه، ولكن ظلموا أنفسهم بشركهم وإفسادهم في الأرض، فما نفعتهم آلهتهم التي كانوا يدعُونها ويطلبون منها أن تدفع عنهم الضر لـمَّا جاء أمر ربك بعذابهم، وما زادتهم آلهتهم غير تدمير وإهلاك وخسران.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,102,'وكما أخذتُ أهل القرى الظالمة بالعذاب لمخالفتهم أمري وتكذيبهم برسلي، آخذ غيرهم مِن أهل القرى إذا ظلموا أنفسهم بكفرهم بالله ومعصيتهم له وتكذيبهم لرسله. إنَّ أَخْذه بالعقوبة لأليم موجع شديد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,103,'إن في أخذنا لأهل القرى السابقة الظالمة لعبرةً وعظة لمن خاف عقاب الله وعذابه في الآخرة، ذلك اليوم الذي يُجمع له الناس جميعًا للمحاسبة والجزاء، ويشهده الخلائق كلهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,104,'وما نؤخر يوم القيامة عنكم إلا لانتهاء مدة معدودة في علمنا، لا تزيد ولا تنقص عن تقديرنا لها بحكمتنا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,105,'يوم يأتي يوم القيامة، لا تتكلم نفس إلا بإذن ربها، فمنهم شقي مستحق للعذاب، وسعيد متفضَّل عليه بالنعيم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,106,'فأما الذين شَقُوا في الدنيا لفساد عقيدتهم وسوء أعمالهم، فالنار مستقرهم، لهم فيها من شدة ما هم فيه من العذاب زفير وشهيق، وهما أشنع الأصوات وأقبحها، ماكثين في النار أبدًا ما دامت السموات والأرض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكَّد، إلا ما شاء ربك من إخراج عصاة الموحدين بعد مدَّة من مكثهم في النار. إن ربك -أيها الرسول- فعَّال لما يريد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,107,'فأما الذين شَقُوا في الدنيا لفساد عقيدتهم وسوء أعمالهم، فالنار مستقرهم، لهم فيها من شدة ما هم فيه من العذاب زفير وشهيق، وهما أشنع الأصوات وأقبحها، ماكثين في النار أبدًا ما دامت السموات والأرض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكَّد، إلا ما شاء ربك من إخراج عصاة الموحدين بعد مدَّة من مكثهم في النار. إن ربك -أيها الرسول- فعَّال لما يريد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,108,'وأما الذين رزقهم الله السعادة فيدخلون الجنة خالدين فيها ما دامت السموات والأرض، إلا الفريق الذي شاء الله تأخيره، وهم عصاة الموحدين، فإنهم يبقون في النار فترة من الزمن، ثم يخرجون منها إلى الجنة بمشيئة الله ورحمته، ويعطي ربك هؤلاء السعداء في الجنة عطاء غير مقطوع عنهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,109,'فلا تكن -أيها الرسول- في شك من بطلان ما يعبد هؤلاء المشركون من قومك، ما يعبدون من الأوثان إلا مثل ما يعبد آباؤهم من قبل، وإنا لموفوهم ما وعدناهم تاما غير منقوص. وهذا توجيه لجميع الأمة، وإن كان لفظه موجهًا إلى الرسول صلى الله عليه وسلَّم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,110,'ولقد آتينا موسى الكتاب وهو التوراة، فاختلف فيه قومه، فآمن به جماعة وكفر به آخرون كما فعل قومك بالقرآن. ولولا كلمة سبقت من ربك بأنه لا يعجل لخلقه العذاب، لحلَّ بهم في دنياهم قضاء الله بإهلاك المكذِّبين ونجاة المؤمنين. وإن الكفار من اليهود والمشركين -أيها الرسول- لفي شك -من هذا القرآن- مريب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,111,'وإن كل أولئك الأقوام المختلفين الذين ذكرنا لك -أيها الرسول- أخبارهم ليوفينهم ربك جزاء أعمالهم يوم القيامة، إن خيرًا فخير، وإن شرًا فشر، إن ربك بما يعمل هؤلاء المشركون خبير، لا يخفى عليه شيء من عملهم. وفي هذا تهديد ووعيد لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,112,'فاستقم -أيها النبي- كما أمرك ربك أنت ومن تاب معك، ولا تتجاوزوا ما حدَّه الله لكم، إن ربَّكم بما تعملون من الأعمال كلها بصير، لا يخفى عليه شيء منها، وسيجازيكم عليها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,113,'ولا تميلوا إلى هؤلاء الكفار الظلمة، فتصيبكم النار، وما لكم من دون الله من ناصر ينصركم، ويتولى أموركم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,114,'وأدِّ الصلاة -أيها النبي- على أتمِّ وجه طَرَفَي النهار في الصباح والمساء، وفي ساعات من الليل. إنَّ فِعْلَ الخيرات يكفِّر الذنوب السالفة ويمحو آثارها، والأمر بإقامة الصلاة وبيان أن الحسنات يذهبن السيئات، موعظة لمن اتعظ بها وتذكر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,115,'واصبر -أيها النبي- على الصلاة، وعلى ما تَلْقى من الأذى من مشركي قومك؛ فإن الله لا يضيع ثواب المحسنين في أعمالهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,116,'فهلاَّ وُجد من القرون الماضية بقايا من أهل الخير والصلاح، ينهون أهل الكفر عن كفرهم، وعن الفساد في الأرض، لم يوجد من أولئك الأقوام إلا قليل ممن آمن، فنجَّاهم الله بسبب ذلك مِن عذابه حين أخذ الظالمين. واتَّبع عامتهم من الذين ظلموا أنفسهم ما مُتِّعوا فيه من لذات الدنيا ونعيمها، وكانوا مجرمين ظالمين باتباعهم ما تنعموا فيه، فحقَّ عليهم العذاب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,117,'وما كان ربك -أيها الرسول- ليهلك قرية من القرى وأهلها مصلحون في الأرض، مجتنبون للفساد والظلم، وإنما يهلكهم بسبب ظلمهم وفسادهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,118,'ولو شاء ربك لجعل الناس كلهم جماعة واحدة على دين واحد وهو دين الإسلام، ولكنه سبحانه لم يشأ ذلك، فلا يزال الناس مختلفين في أديانهم؛ وذلك مقتضى حكمته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,119,'إلا مَن رحم ربك فآمنوا به واتبعوا رسله، فإنهم لا يختلفون في توحيد الله وما جاءت به الرسل من عند الله، وقد اقتضت حكمته سبحانه وتعالى أنه خَلَقهم مختلفين: فريق شقيٌّ وفريق سعيد، وكل ميسر لما خُلِق له. وبهذا يتحقق وعد ربك في قضائه وقدره: أنه سبحانه سيملأ جهنم من الجن والإنس الذين اتبعوا إبليس وجنده ولم يهتدوا للإيمان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,120,'ونقصُّ عليك -أيها النبي- من أخبار الرسل الذين كانوا قبلك، كل ما تحتاج إليه مما يقوِّي قلبك للقيام بأعباء الرسالة، وقد جاءك في هذه السورة وما اشتملت عليه من أخبار، بيان الحق الذي أنت عليه، وجاءك فيها موعظة يرتدع بها الكافرون، وذكرى يتذكر بها المؤمنون بالله ورسله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,121,'وقل -أيها الرسول- للكافرين الذين لا يقرُّون بوحدانية الله: اعملوا ما أنتم عاملون على حالتكم وطريقتكم في مقاومة الدعوة وإيذاء الرسول والمستجيبين له، فإنَّا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ أمر الله. وانتظروا عاقبة أمرنا، فإنَّا منتظرون عاقبة أمركم. وفي هذا تهديد ووعيد لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,122,'وقل -أيها الرسول- للكافرين الذين لا يقرُّون بوحدانية الله: اعملوا ما أنتم عاملون على حالتكم وطريقتكم في مقاومة الدعوة وإيذاء الرسول والمستجيبين له، فإنَّا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ أمر الله. وانتظروا عاقبة أمرنا، فإنَّا منتظرون عاقبة أمركم. وفي هذا تهديد ووعيد لهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),11,123,'ولله سبحانه وتعالى علم كل ما غاب في السموات والأرض، وإليه يُرْجَع الأمر كله يوم القيامة، فاعبده -أيها النبي- وفوِّض أمرك إليه، وما ربك بغافل عما تعملون من الخير والشر، وسيجازي كلاًّ بعمله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/11/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=11) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,1,'(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,2,'إنا أنزلنا هذا القرآن بلغة العرب، لعلكم -أيها العرب- تعقلون معانيه وتفهمونها، وتعملون بهديه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,3,'نحن نقصُّ عليك -أيها الرسول- أحسن القصص بوحينا إليك هذا القرآن، وإن كنت قبل إنزاله عليك لمن الغافلين عن هذه الأخبار، لا تدري عنها شيئًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,4,'اذكر -أيها الرسول- لقومك قول يوسف لأبيه: إني رأيت في المنام أحد عشر كوكبًا، والشمس والقمر رأيتهم لي ساجدين. فكانت هذه الرؤيا بشرى لِمَا وصل إليه يوسف عليه السلام من علوِّ المنزلة في الدنيا والآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,5,'قال يعقوب لابنه يوسف: يا بني لا تذكر لإخوتك هذه الرؤيا فيحسدوك، ويعادوك، ويحتالوا في إهلاكك، إن الشيطان للإنسان عدو ظاهر العداوة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,6,'وكما أراك ربك هذه الرؤيا فكذلك يصطفيك ويعلمك تفسير ما يراه الناس في منامهم من الرؤى مما تؤول إليه واقعًا، ويتم نعمته عليك وعلى آل يعقوب بالنبوة والرسالة، كما أتمها من قبل على أبويك إبراهيم وإسحاق بالنبوة والرسالة. إن ربك عليم بمن يصطفيه من عباده، حكيم في تدبير أمور خلقه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,7,'لقد كان في قصة يوسف وإخوته عبر وأدلة تدل على قدرة الله وحكمته لمن يسأل عن أخبارهم، ويرغب في معرفتها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,8,'إذ قال إخوة يوسف من أبيه فيما بينهم: إن يوسف وأخاه الشقيق أحب إلى أبينا منا، يفضِّلهما علينا، ونحن جماعة ذوو عدد، إن أبانا لفي خطأ بيِّن حيث فضَّلهما علينا من غير موجب نراه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,9,'اقتلوا يوسف أو ألقوا به في أرض مجهولة بعيدة عن العُمران يخلُص لكم حب أبيكم وإقباله عليكم، ولا يلتفت عنكم إلى غيركم، وتكونوا مِنْ بعد قَتْل يوسف أو إبعاده تائبين إلى الله، مستغفرين له من بعد ذنبكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,10,'قال قائل من إخوة يوسف: لا تقتلوا يوسف وألقوه في جوف البئر يلتقطه بعض المارَّة من المسافرين فتستريحوا منه، ولا حاجة إلى قتله، إن كنتم عازمين على فعل ما تقولون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,11,'قال إخوة يوسف -بعد اتفاقهم على إبعاده-: يا أبانا ما لك لا تجعلنا أمناء على يوسف مع أنه أخونا، ونحن نريد له الخير ونشفق عليه ونرعاه، ونخصه بخالص النصح؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,12,'أرسله معنا غدًا عندما نخرج إلى مراعينا يَسْعَ وينشط ويفرح، ويلعب بالاستباق ونحوه من اللعب المباح، وإنا لحافظون له من كل ما تخاف عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,13,'قال يعقوب: إني لَيؤلم نفسي مفارقته لي إذا ذهبتم به إلى المراعي، وأخشى أن يأكله الذئب، وأنتم عنه غافلون منشغلون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,14,'قال إخوة يوسف لوالدهم: لئن أكله الذئب، ونحن جماعة قوية إنا إذًا لخاسرون، لا خير فينا، ولا نفع يُرْجَى منا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,15,'فأرْسَلَهُ معهم. فلما ذهبوا به وأجمعوا على إلقائه في جوف البئر، وأوحينا إلى يوسف لتخبرنَّ إخوتك مستقبلا بفعلهم هذا الذي فعلوه بك، وهم لا يُحِسُّون بذلك الأمر ولا يشعرون به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,16,'وجاء إخوة يوسف إلى أبيهم في وقت العِشاء من أول الليل، يبكون ويظهرون الأسف والجزع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,17,'قالوا: يا أبانا إنا ذهبنا نتسابق في الجَرْي والرمي بالسهام، وتركنا يوسف عند زادنا وثيابنا، فلم نقصِّر في حفظه، بل تركناه في مأمننا، وما فارقناه إلا وقتًا يسيرًا، فأكله الذئب، وما أنت بمصدِّق لنا ولو كنا موصوفين بالصدق؛ لشدة حبك ليوسف.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,18,'وجاؤوا بقميصه ملطخًا بدم غير دم يوسف؛ ليشهد على صدقهم، فكان دليلا على كذبهم؛ لأن القميص لم يُمَزَّقْ. فقال لهم أبوهم يعقوب عليه السلام: ما الأمر كما تقولون، بل زيَّنت لكم أنفسكم الأمَّارة بالسوء أمرًا قبيحًا في يوسف، فرأيتموه حسنًا وفعلتموه، فصبري صبر جميل لا شكوى معه لأحد من الخلق، وأستعين بالله على احتمال ما تصفون من الكذب، لا على حولي وقوتي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,19,'وجاءت جماعة من المسافرين، فأرسلوا مَن يطلب لهم الماء، فلما أرسل دلوه في البئر تعلَّق بها يوسف، فقال واردهم: يا بشراي هذا غلام نفيس، وأخفى الواردُ وأصحابه يوسفَ من بقية المسافرين فلم يظهروه لهم، وقالوا: إن هذه بضاعة استبضعناها، والله عليم بما يعملونه بيوسف.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,20,'وباعه إخوته للواردين من المسافرين بثمن قليل من الدراهم، وكانوا زاهدين فيه راغبين في التخلص منه؛ وذلك أنهم لا يعلمون منزلته عند الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,21,'ولما ذهب المسافرون بيوسف إلى "مصر" اشتراه منهم عزيزها، وهو الوزير، وقال لامرأته: أحسني معاملته، واجعلي مقامه عندنا كريمًا، لعلنا نستفيد من خدمته، أو نقيمه عندنا مقام الولد، وكما أنجينا يوسف وجعلنا عزيز "مصر" يَعْطِف عليه، فكذلك مكنَّا له في أرض "مصر"، وجعلناه على خزائنها، ولنعلِّمه تفسير الرؤى فيعرف منها ما سيقع مستقبلا. والله غالب على أمره، فحكمه نافذ لا يبطله مبطل، ولكن أكثر الناس لا يعلمون أن الأمر كله بيد الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,22,'ولما بلغ يوسف منتهى قوته في شبابه أعطيناه فهمًا وعلمًا، ومثل هذا الجزاء الذي جزينا به يوسف على إحسانه نجزي المحسنين على إحسانهم. وفي هذا تسلية للرسول صلى الله عليه وسلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,23,'ودعت امرأة العزيز -برفق ولين- يوسف الذي هو في بيتها إلى نفسها؛ لحبها الشديد له وحسن بهائه، وغلَّقت الأبواب عليها وعلى يوسف، وقالت: هلمَّ إليَّ، فقال: معاذ الله أعتصم به، وأستجير مِن الذي تدعينني إليه، من خيانة سيدي الذي أحسن منزلتي وأكرمني فلا أخونه في أهله، إنه لا يفلح مَن ظَلَم فَفَعل ما ليس له فعله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,24,'ولقد مالت نفسها لفعل الفاحشة، وحدَّثت يوسفَ نفسُه حديث خطرات للاستجابة، لولا أن رأى آية من آيات ربه تزجره عمَّا حدثته به نفسه، وإنما أريناه ذلك؛ لندفع عنه السوء والفاحشة في جميع أموره، إنه من عبادنا المطهرين المصطفَين للرسالة الذين أخلصوا في عبادتهم لله وتوحيده.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,25,'وأسرع يوسف إلى الباب يريد الخروج، وأسرعت تحاول الإمساك به، وجذبت قميصه من خلفه؛ لتحول بينه وبين الخروج فشقَّته، ووجدا زوجها عند الباب فقالت: ما جزاء مَن أراد بامرأتك فاحشة إلا أن يسجن أو يعذب العذاب الموجع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,26,'قال يوسف: هي التي طلبت مني ذلك، فشهد صبي في المهد مِن أهلها فقال: إن كان قميصه شُقَّ من الأمام فصدقت في اتِّهامها له، وهو من الكاذبين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,27,'وإن كان قميصه شُقَّ من الخلف فكذبت في قولها، وهو من الصادقين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,28,'فلما رأى الزوج قميص يوسف شُقَّ من خلفه علم براءة يوسف، وقال لزوجته: إن هذا الكذب الذي اتهمتِ به هذا الشاب هو مِن جملة مكركن -أيتها النساء-، إنَّ مكركن عظيم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,29,'قال عزيز "مصر": يا يوسف اترك ذِكْر ما كان منها فلا تذكره لأحد، واطلبي -أيتها المرأة- المغفرة لذنبك؛ إنك كنتِ من الآثمين في مراودة يوسف عن نفسه، وفي افترائك عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,30,'ووصل الخبر إلى نسوة في المدينة فتحدثن به، وقلن منكرات على امرأة العزيز: امرأة العزيز تحاول غلامها عن نفسه، وتدعوه إلى نفسها، وقد بلغ حبها له شَغَاف قلبها (وهو غلافه)، إنا لَنراها في هذا الفعل لفي ضلال واضح.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,31,'فلما سمعت امرأة العزيز بغِيْبتهن إياها واحتيالهن في ذمِّها، أرسلت إليهن تدعوهن لزيارتها، وهيَّأت لهن ما يتكئن عليه من الوسائد، وما يأكلنه من الطعام، وأعطت كل واحدة منهن سكينًا ليُقَطِّعن الطعام، ثم قالت ليوسف: اخرج عليهن، فلما رأينه أعظمنه وأجللنه، وأخَذَهن حسنه وجماله، فجرحن أيديهن وهن يُقَطِّعن الطعام من فرط الدهشة والذهول، وقلن متعجبات: معاذ الله، ما هذا من جنس البشر؛ لأن جماله غير معهود في البشر، ما هو إلا مَلَك كريم من الملائكة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,32,'قالت امرأة العزيز للنسوة اللاتي قطَّعن أيديهن: فهذا الذي أصابكن في رؤيتكن إياه ما أصابكن هو الفتى الذي لُمتُنَّني في الافتتان به، ولقد طلبته وحاولت إغراءه؛ ليستجيب لي فامتنع وأبى، ولئن لم يفعل ما آمره به مستقبلا لَيعاقَبَنَّ بدخول السجن، ولَيكونن من الأذلاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,33,'قال يوسف مستعيذًا مِن شرهن ومكرهن: يا ربِّ السجنُ أحب إليَّ مما يدعونني إليه من عمل الفاحشة، وإن لم تدفع عني مكرهن أَمِلْ إليهن، وأكن من السفهاء الذين يرتكبون الإثم لجهلهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,34,'فاستجاب الله ليوسف دعاءه فصرف عنه ما أرادت منه امرأة العزيز وصواحباتها من معصية الله. إن الله هو السميع لدعاء يوسف، ودعاء كل داع مِن خلقه، العليم بمطلبه وحاجته وما يصلحه، وبحاجة جميع خلقه وما يصلحهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,35,'ثم ظهر للعزيز وأصحابه -من بعد ما رأوا الأدلة على براءة يوسف وعفته- أن يسجنوه إلى زمن يطول أو يقصر؛ منعًا للفضيحة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,36,'ودخل السجن مع يوسف فَتَيان، قال أحدهما: إني رأيت في المنام أني أعصر عنبًا ليصير خمرًا، وقال الآخر: إني رأيت أني أحمل فوق رأسي خبزًا تأكل الطير منه، أخبرنا -يا يوسف -بتفسير ما رأينا، إنا نراك من الذين يحسنون في عبادتهم لله، ومعاملتهم لخلقه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,37,'قال لهما يوسف: لا يأتيكما طعام ترزقانه في حال من الأحوال إلا أخبرتكما بتفسيره قبل أن يأتيكما، ذلكما التعبير الذي سأعبِّره لكما مما علَّمني ربي؛ إني آمنت به، وأخلصت له العبادة، وابتعدت عن دين قوم لا يؤمنون بالله، وهم بالبعث والحساب جاحدون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,38,'واتبعت دين آبائي إبراهيم وإسحاق ويعقوب فعبدت الله وحده، ما كان لنا أن نجعل لله شريكًا في عبادته، ذلك التوحيد بإفراد الله بالعبادة، مما تفضل الله به علينا وعلى الناس، ولكن أكثر الناس لا يشكرون الله على نعمة التوحيد والإيمان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,39,'وقال يوسف للفَتَيين اللذين معه في السجن: أعبادةُ آلهةٍ مخلوقة شتى خير أم عبادة الله الواحد القهار؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,40,'ما تعبدون من دون الله إلا أسماءً لا معاني وراءها، جعلتموها أنتم وآباؤكم أربابًا جهلا منكم وضلالا، ما أنزل الله من حجة أو برهان على صحتها، ما الحكم الحق إلا لله تعالى وحده، لا شريك له، أمر ألا تنقادوا ولا تخضعوا لغيره، وأن تعبدوه وحده، وهذا هو الدين القيم الذي لا عوج فيه، ولكن أكثر الناس يجهلون ذلك، فلا يعلمون حقيقته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,41,'يا صاحبيَّ في السجن، إليكما تفسيرَ رؤياكما: أما الذي رأى أنه يعصر العنب في رؤياه فإنه يخرج من السجن ويكون ساقي الخمر للملك، وأما الآخر الذي رأى أنه يحمل على رأسه خبزًا فإنه يُصْلب ويُتْرك، وتأكل الطير من رأسه، قُضي الأمر الذي فيه تستفتيان وفُرغ منه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,42,'وقال يوسف للذي علم أنه ناجٍ من صاحبيه: اذكرني عند سيِّدك الملك وأخبره بأني مظلوم محبوس بلا ذنب، فأنسى الشيطان ذلك الرجل أن يذكر للملك حال يوسف، فمكث يوسف بعد ذلك في السجن عدة سنوات.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,43,'وقال الملك: إني رأيت في منامي سبع بقرات سمان، يأكلهن سبع بقرات نحيلات من الهُزال، ورأيت سبع سنبلات خضر، وسبع سنبلات يابسات، يا أيها السادة والكبراء أخبروني عن هذه الرؤيا، إن كنتم للرؤيا تُفَسِّرون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,44,'قالوا: رؤياك هذه أخلاط أحلام لا تأويل لها، وما نحن بتفسير الأحلام بعالمين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,45,'وقال الذي نجا من القتل من صاحبَي يوسف في السجن وتذكر بعد مدة ما نسي من أمر يوسف: أنا أخبركم بتأويل هذه الرؤيا، فابعثوني إلى يوسف لآتيكم بتفسيرها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,46,'وعندما وصل الرجل إلى يوسف قال له: يوسف أيها الصديق فسِّر لنا رؤيا مَن رأى سبع بقرات سمان يأكلهن سبع بقرات هزيلات، ورأى سبع سنبلات خضر وأخر يابسات؛ لعلي أرجع إلى الملك وأصحابه فأخبرهم؛ ليعلموا تأويل ما سألتك عنه، وليعلموا مكانتك وفضلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,47,'قال يوسف لسائله عن رؤيا الملك: تفسير هذه الرؤيا أنكم تزرعون سبع سنين متتابعة جادِّين ليَكْثُر العطاء، فما حصدتم منه في كل مرة فادَّخِروه، واتركوه في سنبله؛ ليتمَّ حفظه من التسوُّس، وليكون أبقى، إلا قليلا مما تأكلونه من الحبوب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,48,'ثم يأتي بعد هذه السنين الخِصْبة سبع سنين شديدة الجَدْب، يأكل أهلها كل ما ادَّخرتم لهن من قبل، إلا قليلا مما تحفظونه وتدَّخرونه ليكون بذورًا للزراعة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,49,'ثم يأتي من بعد هذه السنين المجدبة عام يغاث فيه الناس بالمطر، فيرفع الله تعالى عنهم الشدة، ويعصرون فيه الثمار من كثرة الخِصْب والنماء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,50,'وقال الملك لأعوانه: أخرجوا الرجل المعبِّر للرؤيا من السجن وأحضروه لي، فلما جاءه رسول الملك يدعوه قال يوسف للرسول: ارجع إلى سيدك الملك، واطلب منه أن يسأل النسوة اللاتي جرحن أيديهن عن حقيقة أمرهن وشأنهن معي؛ لتظهر الحقيقة للجميع، وتتضح براءتي، إن ربي عليم بصنيعهن وأفعالهن لا يخفى عليه شيء من ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,51,'قال الملك للنسوة اللاتي جرحن أيديهن: ما شأنكن حين راودتنَّ يوسف عن نفسه يوم الضيافة؟ فهل رأيتن منه ما يريب؟ قلن: معاذ الله ما علمنا عليه أدنى شيء يَشينه، عند ذلك قالت امراة العزيز: الآن ظهر الحق بعد خفائه، فأنا التي حاولت فتنته بإغرائه فامتنع، وإنه لمن الصادقين في كل ما قاله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,52,'ذلك القول الذي قلته في تنزيهه والإقرار على نفسي ليعلم زوجي أني لم أخنه بالكذب عليه، ولم تقع مني الفاحشة، وأنني راودته، واعترفت بذلك لإظهار براءتي وبراءته، وأن الله لا يوفق أهل الخيانة، ولا يرشدهم في خيانتهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,53,'قالت امرأة العزيز: وما أزكي نفسي ولا أبرئها، إن النفس لكثيرة الأمر لصاحبها بعمل المعاصي طلبا لملذاتها، إلا مَن عصمه الله. إن الله غفور لذنوب مَن تاب مِن عباده، رحيم بهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,54,'وقال الملك الحاكم لـ "مصر" حين بلغته براءة يوسف: جيئوني به أجعله من خلصائي وأهل مشورتي، فلما جاء يوسف وكلَّمه الملك، وعرف براءته، وعظيم أمانته، وحسن خلقه، قال له: إنك اليوم عندنا عظيم المكانة، ومؤتمن على كل شيء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,55,'وأراد يوسف أن ينفع العباد، ويقيم العدل بينهم، فقال للملك: اجعلني واليًا على خزائن "مصر"، فإني خازن أمين، ذو علم وبصيرة بما أتولاه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,56,'وكما أنعم الله على يوسف بالخلاص من السجن مكَّن له في أرض "مصر" ينزل منها أي منزل شاءه. يصيب الله برحمته من يشاء من عباده المتقين، ولا يضيع أجر مَن أحسن شيئًا مِن العمل الصالح.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,57,'ولَثواب الآخرة عند الله أعظم من ثواب الدنيا لأهل الإيمان والتقوى الذين يخافون عقاب الله، ويطيعونه في أمره ونهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,58,'وقدِمَ إخوة يوسف إلى "مصر" -بعد أن حلَّ بهم الجدب في أرضهم-؛ ليجلبوا منها الطعام، فدخلوا عليه فعرفهم، ولم يعرفوه لطول المدة وتغيُّر هيئته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,59,'وقد أمر يوسف بإكرامهم وحسن ضيافتهم، ثم أعطاهم من الطعام ما طلبوا، وكانوا قد أخبروه أن لهم أخًا من أبيهم لم يُحضروه معهم -يريدون شقيقه- فقال: ائتوني بأخيكم من أبيكم، ألم تروا أني أوفيتُ لكم الكيل وأكرمتكم في الضيافة، وأنا خير المضيفين لكم؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,60,'فإن لم تأتوني به فليس لكم عندي طعام أكيله لكم، ولا تأتوا إليَّ.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,61,'قالوا: سنبذل جهدنا لإقناع أبيه أن يرسله معنا، ولن نقصِّر في ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,62,'وقال يوسف لغلمانه: اجعلوا ثمن ما أخذوه في أمتعتهم سرًا؛ رجاء أن يعرفوه إذا رجعوا إلى أهلهم، ويقدِّروا إكرامنا لهم؛ ليرجعوا طمعًا في عطائنا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,63,'فلما رجعوا إلى أبيهم قصُّوا عليه ما كان من إكرام العزيز لهم، وقالوا: إنه لن يعطينا مستقبَلا إلا إذا كان معنا أخونا الذي أخبرناه به، فأرسلْه معنا نحضر الطعام وافيًا، ونتعهد لك بحفظه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,64,'قال لهم أبوهم: كيف آمنكم على "بنيامين" وقد أمنتكم على أخيه يوسف من قبل، والتزمتم بحفظه فلم تفوا بذلك؟ فلا أثق بالتزامكم وحفظكم، ولكني أثق بحفظ الله، خير الحافظين وأرحم الراحمين، أرجو أن يرحمني فيحفظه ويرده عليَّ.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,65,'ولما فتحوا أوعيتهم وجدوا ثمن بضاعتهم الذي دفعوه قد رُدَّ إليهم قالوا: يا أبانا ماذا نطلب أكثر من هذا؟ هذا ثمن بضاعتنا ردَّه العزيز إلينا، فكن مطمئنًا على أخينا، وأرسله معنا؛ لنجلب طعامًا وفيرًا لأهلنا، ونحفظ أخانا، ونزداد حِمْلَ بعير له؛ فإن العزيز يكيل لكل واحد حِمْلَ بعير، وذلك كيل يسير عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,66,'قال لهم يعقوب: لن أتركه يذهب معكم حتى تتعهدوا وتحلفوا لي بالله أن تردوه إليَّ، إلا أن تُغْلبوا عليه فلا تستطيعوا تخليصه، فلما أعطَوْه عهد الله على ما طلب، قال يعقوب: الله على ما نقول وكيل، أي تكفينا شهادته علينا وحفظه لنا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,67,'وقال لهم أبوهم: يا أبنائي إذا دخلتم أرض "مصر" فلا تدخلوا مِن باب واحد، ولكن ادخلوها من أبواب متفرقة، حتى لا تصيبكم العين، وإني إذ أوصيكم بهذا لا أدفع عنكم شيئًا قضاه الله عليكم، فما الحكم إلا لله وحده، عليه اعتمدت ووثقت، وعليه وحده يعتمد المؤمنون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,68,'ولما دخلوا من أبواب متفرقة كما أمرهم أبوهم، ما كان ذلك ليدفع قضاء الله عنهم، ولكن كان شفقة في نفس يعقوب عليهم أن تصيبهم العين، وإن يعقوب لصاحب علمٍ عظيم بأمر دينه علَّمه الله له وحْيًا، ولكن أكثر الناس لا يعلمون عواقب الأمور ودقائق الأشياء، وما يعلمه يعقوب -عليه السلام- مِن أمر دينه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,69,'ولما دخل إخوة يوسف عليه في منزل ضيافته ومعهم شقيقه، ضم يوسف إليه شقيقه، وقال له سرًا: إني أنا أخوك فلا تحزن، ولا تغتمَّ بما صنعوه بي فيما مضى. وأمره بكتمان ذلك عنهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,70,'فلما جهزَّهم يوسف، وحمَّل إبلهم بالطعام، أمر عماله، فوضعوا الإناء الذي كان يكيل للناس به في متاع أخيه "بنيامين" من حيث لا يشعر أحد، ولما ركبوا ليسيروا نادى منادٍ قائلا يا أصحاب هذه العير المحمَّلة بالطعام، إنكم لسارقون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,71,'قال أولاد يعقوب مقبلين على المنادي: ما الذي تفقدونه؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,72,'قال المنادي ومَن بحضرته: نفقد المكيال الذي يكيل الملك به، ومكافأة من يحضره مقدار حِمْل بعير من الطعام، وقال المنادي: وأنا بحِمْل البعير من الطعام ضامن وكفيل.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,73,'قال إخوة يوسف: والله لقد تحققتم مما شاهدتموه منا أننا ما جئنا أرض "مصر" من أجل الإفساد فيها، وليس من صفاتنا أن نكون سارقين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,74,'قال المكلَّفون بالبحث عن المكيال لإخوة يوسف: فما عقوبة السارق عندكم إن كنتم كاذبين في قولكم: لسنا بسارقين؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,75,'قال إخوة يوسف: جزاء السارق مَن وُجِد المسروق في رحله فهو جزاؤه. أي يسلَّم بسرقته إلى مَن سرق منه حتى يكون عبدًا عنده، مثل هذا الجزاء -وهو الاسترقاق- نجزي الظالمين بالسرقة، وهذا ديننا وسنتنا في أهل السرقة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,76,'ورجعوا بإخوة يوسف إليه، فقام بنفسه يفتش أمتعتهم، فبدأ بأمتعتهم قبل متاع شقيقه؛ إحكامًا لما دبَّره لاستبقاء أخيه معه، ثم انتهى بوعاء أخيه، فاستخرج الإناء منه، كذلك يسَّرنا ليوسف هذا التدبير الذي توصَّل به لأخذ أخيه، وما كان له أن يأخذ أخاه في حكم مَلِك "مصر"؛ لأنه ليس من دينه أن يتملك السارق، إلا أن مشيئة الله اقتضت هذا التدبير والاحتكام إلى شريعة إخوة يوسف القاضية برِقِّ السارق. نرفع منازل مَن نشاء في الدنيا على غيره كما رفعنا منزلة يوسف. وفوق كل ذي علمٍ من هو أعلم منه، حتى ينتهي العلم إلى الله تعالى عالم الغيب والشهادة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,77,'قال إخوة يوسف: إنْ سرق هذا فقد سرق أخ شقيق له من قبل (يقصدون يوسف عليه السلام) فأخفى يوسف في نفسه ما سمعه، وحدَّث نفسه قائلا أنتم أسوأ منزلة ممن ذكرتم، حيث دبَّرتم لي ما كان منكم، والله أعلم بما تصفون من الكذب والافتراء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,78,'قالوا مستعطفين ليوفوا بعهد أبيهم: يا أيها العزيز إن له والدًا كبيرًا في السن يحبه ولا يطيق بُعده، فخُذْ أحدنا بدلا من "بنيامين"، إنا نراك من المحسنين في معاملتك لنا ولغيرنا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,79,'قال يوسف: نعتصم بالله ونستجير به أن نأخذ أحدًا غير الذي وجدنا المكيال عنده -كما حكمتم أنتم-، فإننا إن فعلنا ما تطلبون نكون في عداد الظالمين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,80,'فلما يئسوا من إجابته إياهم لِمَا طلبوه انفردوا عن الناس، وأخذوا يتشاورون فيما بينهم، قال كبيرهم في السن: ألم تعلموا أن أباكم قد أخذ عليكم العهد المؤكد لتردُّنَّ أخاكم إلا أن تُغلبوا، ومن قبل هذا كان تقصيركم في يوسف وغدركم به؛ لذلك لن أفارق أرض "مصر" حتى يأذن لي أبي في مفارقتها، أو يقضي لي ربي بالخروج منها، وأتمكن مِن أَخْذِ أخي، والله خيرُ مَن حَكَمَ، وأعدل مَن فَصَلَ بين الناس.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,81,'ارجعوا أنتم إلى أبيكم، وأخبروه بما جرى، وقولوا له: إن ابنك "بنيامين" قد سرق، وما شهدنا بذلك إلا بعد أن تَيَقَّنَّا، فقد رأينا المكيال في رحله، وما كان عندنا علم الغيب أنه سيسرق حين عاهدناك على ردِّه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,82,'واسأل -يا أبانا- أهل "مصر"، ومَن كان معنا في القافلة التي كنا فيها، وإننا صادقون فيما أخبرناك به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,83,'ولما رجعوا وأخبروا أباهم قال لهم: بل زَيَّنَت لكم أنفسكم الأمَّارة بالسوء مكيدة دبَّرتموها كما فعلتم مِن قبل مع يوسف، فصبري صبر جميل لا جزع فيه ولا شكوى معه، عسى الله أن يردَّ إليَّ أبنائي الثلاثة -وهم يوسف وشقيقه وأخوهم الكبير المتخلف من أجل أخيه- إنه هو العليم بحالي، الحكيم في تدبيره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,84,'وأعرض يعقوب عنهم، وقد ضاق صدره بما قالوه، وقال: يا حسرتا على يوسف وابيضَّتْ عيناه، بذهاب سوادهما مِن شدة الحزن فهو ممتلئ القلب حزنًا، ولكنه شديد الكتمان له.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,85,'قال بنوه: تالله ما تزال تتذكر يوسف، ويشتدُّ حزنك عليه حتى تُشْرِف على الهلاك أو تهلك فعلا فخفف عن نفسك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,86,'قال يعقوب مجيبًا لهم: لا أظهر همِّي وحزني إلا لله وحده، فهو كاشف الضرِّ والبلاء، وأعلم من رحمة الله وفرجه ما لا تعلمونه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,87,'قال يعقوب: يا أبنائي عودوا إلى "مصر" فاستقصوا أخبار يوسف وأخيه، ولا تقطعوا رجاءكم من رحمة الله، إنه لا يقطع الرجاء من رحمة الله إلا الجاحدون لقدرته، الكافرون به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,88,'فذهبوا إلى "مصر"، فلما دخلوا على يوسف قالوا: يا أيها العزيز أصابنا وأهلنا القحط والجدب، وجئناك بثمن رديء قليل، فأعطنا به ما كنت تعطينا من قبل بالثمن الجيد، وتصدَّقْ علينا بقبض هذه الدراهم المزجاة وتجوَّز فيها، إن الله تعالى يثيب المتفضِّلين على أهل الحاجة بأموالهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,89,'فلما سمع مقالتهم رقَّ لهم، وعرَّفهم بنفسه وقال: هل تذكرون الذي فعلتموه بيوسف وأخيه من الأذى في حال جَهْلكم بعاقبة ما تفعلون؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,90,'قالوا: أإنَّك لأنت يوسف؟ قال: نعم أنا يوسف، وهذا شقيقي، قد تفضَّل الله علينا، فجمع بيننا بعد الفرقة، إنه من يتق الله، ويصبر على المحن، فإن الله لا يذهب ثواب إحسانه، وإنما يجزيه أحسن الجزاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,91,'قالوا: تالله لقد فَضَّلك الله علينا وأعزَّك بالعلم والحلم والفضل، وإن كنا لخاطئين بما فعلناه عمدًا بك وبأخيك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,92,'قال لهم يوسف: لا تأنيب عليكم اليوم، يغفر الله لكم، وهو أرحم الراحمين لمن تاب من ذنبه وأناب إلى طاعته.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,93,'ولما سألهم عن أبيه أخبروه بذهاب بصره من البكاء عليه، فقال لهم: عودوا إلى أبيكم ومعكم قميصي هذا فاطرحوه على وجه أبي يَعُدْ إليه بصره، ثم أحضروا إليَّ جميع أهلكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,94,'ولما خرجت القافلة من أرض "مصر"، ومعهم القميص قال يعقوب لمن حضره: إني لأجد ريح يوسف لولا أن تسفهوني وتسخروا مني، وتزعموا أن هذا الكلام صدر مني من غير شعور.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,95,'قال الحاضرون عنده: تالله إنك لا تزال في خطئك القديم مِن حب يوسف، وأنك لا تنساه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,96,'فلما أن جاء من يُبشِّر يعقوب بأن يوسف حيٌّ، وطرح قميص يوسف على وجهه فعاد يعقوب مبصرًا، وعمَّه السرور فقال لمن عنده: ألـمْ أخبركم أني أعلم من الله ما لا تعلمونه من فضل الله ورحمته وكرمه؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,97,'قال بنوه: يا أبانا سل لنا ربك أن يعفو عنا ويستر علينا ذنوبنا، إنا كنا خاطئين فيما فعلناه بيوسف وشقيقه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,98,'قال يعقوب: سوف أسأل ربي أن يغفر لكم ذنوبكم، إنه هو الغفور لذنوب عباده التائبين، الرحيم بهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,99,'وخرج يعقوب وأهله إلى "مصر" قاصدين يوسف، فلما وصلوا إليه ضمَّ يوسف إليه أبويه، وقال لهم: ادخلوا "مصر" بمشيئة الله، وأنتم آمنون من الجهد والقحط، ومن كل مكروه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,100,'وأجْلَسَ أباه وأمه على سرير ملكه بجانبه؛ إكرامًا لهما، وحيَّاه أبواه وإخوته الأحد عشر بالسجود له تحية وتكريمًا، لا عبادة وخضوعًا، وكان ذلك جائزًا في شريعتهم، وقد حَرُم في شريعتنا؛ سدًا لذريعة الشرك بالله. وقال يوسف لأبيه: هذا السجود هو تفسير رؤياي التي قصصتها عليك من قبل في صغري، قد جعلها ربي صدقًا، وقد تفضَّل عليَّ حين أخرجني من السجن، وجاء بكم إليَّ من البادية، من بعد أن أفسد الشيطان رابطة الأخوة بيني وبين إخوتي. إن ربي لطيف التدبير لما يشاء، إنه هو العليم بمصالح عباده، الحكيم في أقواله وأفعاله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,101,'ثم دعا يوسف ربه قائلا ربِّ قد أعطيتني من ملك "مصر"، وعلَّمتني من تفسير الرؤى وغير ذلك من العلم، يا خالق السموات والأرض ومبدعهما، أنت متولي جميع شأني في الدنيا والآخرة، توفني إليك مسلمًا، وألحقني بعبادك الصالحين من الأنبياء الأبرار والأصفياء الأخيار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,102,'ذلك المذكور من قصة يوسف هو من أخبار الغيب نخبرك به -أيها الرسول- وحيًا، وما كنت حاضرًا مع إخوة يوسف حين دبَّروا له الإلقاء في البئر، واحتالوا عليه وعلى أبيه. وهذا يدل على صدقك، وأن الله يُوحِي إليك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,103,'وما أكثرُ المشركين من قومك -أيها الرسول- بمصدِّقيك ولا متبعيك، ولو حَرَصْتَ على إيمانهم، فلا تحزن على ذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,104,'وما تطلب من قومك أجرة على إرشادهم للإيمان، إن الذي أُرسلتَ به من القرآن والهدى عظة للناس أجمعين يتذكرون به ويهتدون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,105,'وكثير من الدلائل الدالة على وحدانية الله وقدرته منتشرة في السموات والأرض، كالشمس والقمر والجبال والأشجار، يشاهدونها وهم عنها معرضون، لا يفكرون فيها ولا يعتبرون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,106,'وما يُقِرُّ هؤلاء المعرضون عن آيات الله بأن الله خالقهم ورازقهم وخالق كل شيء ومستحق للعبادة وحده إلا وهم مشركون في عبادتهم الأوثان والأصنام. تعالى الله عن ذلك علوًّا كبيرا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,107,'فهل عندهم ما يجعلهم آمنين أن ينزل بهم عذاب من الله يعُمُّهم، أو أن تأتيهم القيامة فجأة، وهم لا يشعرون ولا يُحِسُّون بذلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,108,'قل لهم -أيها الرسول-: هذه طريقتي، أدعو إلى عبادة الله وحده، على حجة من الله ويقين، أنا ومن اقتدى بي، وأنزِّه الله سبحانه وتعالى عن الشركاء، ولستُ من المشركين مع الله غيره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,109,'وما أرسلنا من قبلك -أيها الرسول- للناس إلا رجالا منهم ننزل عليهم وحينا، وهم من أهل الحاضرة، فهم أقدر على فهم الدعوة والرسالة، يصدقهم المهتدون للحق، ويكذبهم الضالون عنه، أفلم يمشوا في الأرض، فيعاينوا كيف كان مآل المكذبين السابقين وما حلَّ بهم من الهلاك؟ ولَثواب الدار الآخرة أفضل من الدنيا وما فيها للذين آمنوا وخافوا ربهم. أفلا تتفكرون فتعتبروا؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,110,'ولا تستعجل -أيها الرسول- النصر على مكذبيك، فإن الرسل قبلك ما كان يأتيهم النصر عاجلا لحكمة نعلمها، حتى إذا يئس الرسل من قومهم، وأيقنوا أن قومهم قد كذبوهم ولا أمل في إيمانهم، جاءهم نصرنا عند شدة الكرب، فننجي من نشاء من الرسل وأتباعهم، ولا يُرَدُّ عذابنا عمَّن أجرم وتجرَّأ على الله. وفي هذا تسلية للنبي صلى الله عليه وسلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),12,111,'لقد كان في نبأ المرسلين الذي قصصناه عليك وما حلَّ بالمكذبين عظة لأهل العقول السليمة. ما كان هذا القرآن حديثًا مكذوبًا مختلَقًا، ولكن أنزلناه مصدقًا لما سبقه من الكتب السماوية، وبيانًا لكل ما يحتاج إليه العباد من تحليل وتحريم، ومحبوب ومكروه وغير ذلك، وإرشادًا من الضلال، ورحمة لأهل الإيمان تهتدي به قلوبهم، فيعملون بما فيه من الأوامر والنواهي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/12/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=12) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,1,'(المر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,2,'الله تعالى هو الذي رفع السموات السبع بقدرته من غير عمد كما ترونها، ثم استوى -أي علا وارتفع- على العرش استواء يليق بجلاله وعظمته، وذلَّل الشمس والقمر لمنافع العباد، كلٌّ منهما يدور في فلكه إلى يوم القيامة. يدبِّر سبحانه أمور الدنيا والآخرة، يوضح لكم الآيات الدالة على قدرته وأنه لا إله إلا هو؛ لتوقنوا بالله والمعاد إليه، فتصدقوا بوعده ووعيده وتُخْلصوا العبادة له وحده.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,3,'وهو سبحانه الذي جعل الأرض متسعة ممتدة، وهيأها لمعاشكم، وجعل فيها جبالا تُثبِّتُها وأنهارًا لشربكم ومنافعكم، وجعل فيها من كل الثمرات صنفين اثنين، فكان منها الأبيض والأسود والحلو والحامض، وجعل الليل يغطي النهار بظلمته، إن في ذلك كله لَعظات لقوم يتفكرون فيها، فيتعظون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,4,'وفي الأرض قطع يجاور بعضها بعضًا، منها ما هو طيِّب يُنبتُ ما ينفع الناس، ومنها سَبِخة مِلْحة لا تُنبت شيئًا، وفي الأرض الطيبة بساتين من أعناب، وجعل فيها زروعًا مختلفة ونخيلا مجتمعًا في منبت واحد، وغير مجتمع فيه، كل ذلك في تربة واحدة، ويشرب من ماء واحد، ولكنه يختلف في الثمار والحجم والطعم وغير ذلك، فهذا حلو وهذا حامض، وبعضها أفضل من بعض في الأكل، إن في ذلك لَعلامات لمن كان له قلب يعقل عن الله تعالى أمره ونهيه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,5,'وإن تعجب -أيها الرسول- من عدم إيمانهم بعد هذه الأدلة فالعجب الأشدُّ من قول الكفار: أإذا متنا وكنا ترابا نُبعث من جديد؟ أولئك هم الجاحدون بربهم الذي أوجدهم من العدم، وأولئك تكون السلاسل من النار في أعناقهم يوم القيامة، وأولئك يدخلون النار، ولا يخرجون منها أبدًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,6,'ويستعجلك المكذِّبون بالعقوبة التي لم أعاجلهم بها قبل الإيمان الذي يرجى به الأمان والحسنات، وقد مضت عقوبات المكذبين مِن قبلهم، فكيف لا يعتبرون بهم؟ وإن ربك -أيها الرسول- لَذو مغفرة لذنوبِ مَن تاب مِن ذنوبه من الناس على ظلمهم، يفتح لهم باب المغفرة، ويدعوهم إليها، وهم يظلمون أنفسهم بعصيانهم ربهم، وإن ربك لشديد العقاب على مَن أصرَّ على الكفر والضلال ومعصية الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,7,'ويقول كفار "مكة": هلا جاءته معجزة محسوسة كعصا موسى وناقة صالح، وليس ذلك بيدك -أيها الرسول- فما أنت إلا مبلِّغ لهم، ومخوِّف مِن بأس الله. ولكل أمة رسول يرشدهم إلى الله تعالى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,8,'الله تعالى يعلم ما تحمل كلُّ أنثى في بطنها، أذكر هو أم أنثى؟ وشقي هو أم سعيد؟ ويعلم ما تنقصه الأرحام، فيسقط أو يولد قبل تسعة أشهر، وما يزيد حمله عليها. وكل شيء مقدَّر عند الله بمقدار من النقصان أو الزيادة لا يتجاوزه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,9,'الله عالم بما خفي عن الأبصار، وبما هو مشاهَد، الكبير في ذاته وأسمائه وصفاته، المتعال على جميع خلقه بذاته وقدرته وقهره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,10,'يستوي في علمه تعالى مَن أخفى القول منكم ومَن جهر به، ويستوي عنده مَن استتر بأعماله في ظلمة الليل، ومن جهر بها في وضح النهار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,11,'لله تعالى ملائكة يتعاقبون على الإنسان من بين يديه ومن خلفه، يحفظونه بأمر الله ويحصون ما يصدر عنه من خير أو شر. إن الله سبحانه وتعالى لا يغيِّر نعمة أنعمها على قوم إلا إذا غيَّروا ما أمرهم به فعصوه. وإذا أراد الله بجماعةٍ بلاءً فلا مفرَّ منه، وليس لهم مِن دون الله مِن وال يتولى أمورهم، فيجلب لهم المحبوب، ويدفع عنهم المكروه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,12,'هو الذي يريكم من آياته البرق -وهو النور اللامع من خلال السحاب- فتخافون أن تنزل عليكم منه الصواعق المحرقة، وتطمعون أن ينزل معه المطر، وبقدرته سبحانه يوجد السحاب المحمَّل بالماء الكثير لمنافعكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,13,'ويسبِّح الرعد بحمد الله تسبيحًا يدل على خضوعه لربه، وتنزِّه الملائكة ربها مِن خوفها من الله، ويرسل الله الصواعق المهلكة فيهلك بها مَن يشاء من خلقه، والكفار يجادلون في وحدانية الله وقدرته على البعث، وهو شديد الحول والقوة والبطش بمن عصاه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,14,'لله سبحانه وتعالى وحده دعوة التوحيد (لا إله إلا الله)، فلا يُعبد ولا يُدعى إلا هو، والآلهة التي يعبدونها من دون الله لا تجيب دعاء مَن دعاها، وحالهم معها كحال عطشان يمد يده إلى الماء من بعيد؛ ليصل إلى فمه فلا يصل إليه، وما سؤال الكافرين لها إلا غاية في البعد عن الصواب لإشراكهم بالله غيره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,15,'ولله وحده يسجد خاضعًا منقادًا كُلُّ مَن في السموات والأرض، فيسجد ويخضع له المؤمنون طوعًا واختيارًا، ويخضع له الكافرون رغمًا عنهم؛ لأنهم يستكبرون عن عبادته، وحالهم وفطرتهم تكذِّبهم في ذلك، وتنقاد لعظمته ظلال المخلوقات، فتتحرك بإرادته أول النهار وآخره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,16,'قل -أيها الرسول- للمشركين: مَن خالق السَّموات والأرض ومدبِّرهما؟ قل: الله هو الخالق المدبر لهما، وأنتم تقرون بذلك، ثم قل لهم ملزمًا بالحجة: أجعلتم غيره معبودين لكم، وهم لا يَقْدرون على نفع أنفسهم أو ضرها فضلا عن نفعكم أو ضركم، وتركتم عبادة مالكها؟ قل لهم -أيها الرسول-: هل يستوي عندكم الكافر -وهو كالأعمى- والمؤمن وهو كالبصير؟ أم هل يستوي عندكم الكفر -وهو كالظلمات- والإيمان -وهو كالنور؟ أم أن أولياءهم الذين جعلوهم شركاء لله يخلقون مثل خَلْقه، فتشابه عليهم خَلْق الشركاء بخلق الله، فاعتقدوا استحقاقهم للعبادة؟ قل لهم -أيها الرسول-: الله تعالى خالق كل كائن من العدم، وهو المستحق للعبادة وحده، وهو الواحد القهار الذي يستحق الألوهية والعبادة، لا الأصنام والأوثان التي لا تضرُّ ولا تنفع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,17,'ثم ضرب الله سبحانه مثلا للحق والباطل بماء أنزله من السماء، فجَرَت به أودية الأرض بقدر صغرها وكبرها، فحمل السيل غثاء طافيًا فوقه لا نفع فيه. وضرب مثلا آخر: هو المعادن يوقِدون عليها النار لصهرها طلبًا للزينة كما في الذهب والفضة، أو طلبًا لمنافع ينتفعون بها كما في النحاس، فيخرج منها خبثها مما لا فائدة فيه كالذي كان مع الماء، بمثل هذا يضرب الله المثل للحق والباطل: فالباطل كغثاء الماء يتلاشى أو يُرْمى إذ لا فائدة منه، والحق كالماء الصافي، والمعادن النقية تبقى في الأرض للانتفاع بها، كما بيَّن لكم هذه الأمثال، كذلك يضربها للناس؛ ليتضح الحق من الباطل والهدى من الضلال.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,18,'للمؤمنين الذين أطاعوا الله ورسوله الجنة، والذين لم يطيعوا وكفروا به لهم النار، ولو كانوا يملكون كل ما في الأرض وضِعْفه معه لبذلوه فداء لأنفسهم من عذاب الله يوم القيامة، ولن يُتَقبل منهم، أولئك يحاسَبون على كل ما أسلفوه من عمل سيِّئ، ومسكنهم ومقامهم جهنم تكون لهم فراشًا، وبئس الفراش الذي مهدوه لأنفسهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,19,'هل الذي يعلم أن ما جاءك -أيها الرسول- من عند الله هو الحق فيؤمن به، كالأعمى عن الحق الذي لم يؤمن؟ إنما يتعظ أصحاب العقول السليمة الذين يوفون بعهد الله الذي أمرهم به، ولا ينكثون العهد المؤكد الذي عاهدوا الله عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,20,'هل الذي يعلم أن ما جاءك -أيها الرسول- من عند الله هو الحق فيؤمن به، كالأعمى عن الحق الذي لم يؤمن؟ إنما يتعظ أصحاب العقول السليمة الذين يوفون بعهد الله الذي أمرهم به، ولا ينكثون العهد المؤكد الذي عاهدوا الله عليه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,21,'وهم الذين يَصِلون ما أمرهم الله بوصله كالأرحام والمحتاجين، ويراقبون ربهم، ويخشون أن يحاسبهم على كل ذنوبهم، ولا يغفر لهم منها شيئًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,22,'وهم الذين صبروا على الأذى وعلى الطاعة، وعن المعصية طلبًا لرضا ربهم، وأدَّوا الصلاة على أتمِّ وجوهها، وأدَّوا من أموالهم زكاتهم المفروضة، والنفقات المستحبة في الخفاء والعلن، ويدفعون بالحسنة السيئة فتمحوها، أولئك الموصوفون بهذه الصفات لهم العاقبة المحمودة في الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,23,'تلك العاقبة هي جنات عدن يقيمون فيها لا يزولون عنها، ومعهم الصالحون من الآباء والزوجات والذريات من الذكور والإنات، وتدخل الملائكة عليهم من كل باب؛ لتهنئتهم بدخول الجنة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,24,'تقول الملائكة لهم: سَلِمْتم من كل سوء بسبب صبركم على طاعة الله، فنِعْمَ عاقبة الدار الجنة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,25,'أما الأشقياء فقد وُصِفوا بضد صفات المؤمنين، فهم الذين لا يوفون بعهد الله بإفراده سبحانه بالعبادة بعد أن أكدوه على أنفسهم، وهم الذين يقطعون ما أمرهم الله بوصله مِن صلة الأرحام وغيرها، ويفسدون في الأرض بعمل المعاصي، أولئك الموصوفون بهذه الصفات القبيحة لهم الطرد من رحمة الله، ولهم ما يسوءهم من العذاب الشديد في الدار الآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,26,'الله وحده يوسِّع الرزق لمن يشاء من عباده، ويضيِّق على مَن يشاء منهم، وفرح الكفار بالسَّعة في الحياة الدنيا، وما هذه الحياة الدنيا بالنسبة للآخرة إلا شيء قليل يتمتع به، سُرعان ما يزول.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,27,'ويقول الكفار عنادًا: هلا أُنزل على محمد معجزة محسوسة كمعجزة موسى وعيسى. قل لهم: إن الله يضل مَن يشاء من المعاندين عن الهداية ولا تنفعه المعجزات، ويهدي إلى دينه الحق مَن رجع إليه وطلب رضوانه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,28,'ويهدي الذين تسكن قلوبهم بتوحيد الله وذكره فتطمئن، ألا بطاعة الله وذكره وثوابه تسكن القلوب وتستأنس.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,29,'الذين صدَّقوا بالله ورسوله، وعملوا الأعمال الصالحات لهم فرح وقرة عين، وحال طيبة، ومرجع حسن إلى جنة الله ورضوانه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,30,'كما أرسلنا المرسلين قبلك أرسلناك -أيها الرسول- في أمة قد مضت مِن قبلها أمم المرسلين؛ لتتلو على هذه الأمة القرآن المنزل عليك، وحال قومك الجحود بوحدانية الرحمن، قل لهم -أيها الرسول-: الرحمن الذي لم تتخذوه إلهًا واحدًا هو ربي وحده لا معبود بحق سواه، عليه اعتمدت ووثقت، وإليه مرجعي وإنابتي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,31,'يردُّ الله -تعالى- على الكافرين الذين طلبوا إنزال معجزات محسوسة على النبي صلى الله عليه وسلم فيقول لهم: ولو أن ثمة قرآنًا يقرأ، فتزول به الجبال عن أماكنها، أو تتشقق به الأرض أنهارًا، أو يحيا به الموتى وتُكَلَّم -كما طلبوا منك- لكان هذا القرآن هو المتصف بذلك دون غيره، ولما آمنوا به. بل لله وحده الأمر كله في المعجزات وغيرها. أفلم يعلم المؤمنون أن الله لو يشاء لآمن أهل الأرض كلهم من غير معجزة؟ ولا يزال الكفار تنزل بهم مصيبة بسبب كفرهم كالقتل والأسر في غزوات المسلمين، أو تنزل تلك المصيبة قريبًا من دارهم، حتى يأتي وعد الله بالنصر عليهم، إن الله لا يخلف الميعاد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,32,'وإذا كانوا قد سخروا من دعوتك -أيها الرسول- فلقد سَخِرَتْ أمم من قبلك برسلهم، فلا تحزن فقد أمهلتُ الذين كفروا، ثم أخذتُهم بعقابي، وكان عقابًا شديدًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,33,'أفمن هو قائم على كل نفس يُحصي عليها ما تعمل، أحق أن يعبد، أم هذه المخلوقات العاجزة؟ وهم -من جهلهم- جعلوا لله شركاء مِن خَلْقه يعبدونهم، قل لهم -أيها الرسول-: اذكروا أسماءهم وصفاتهم، ولن يجدوا من صفاتهم ما يجعلهم أهلا للعبادة، أم تخبرون الله بشركاء في أرضه لا يعلمهم، أم تسمونهم شركاء بظاهر من اللفظ من غير أن يكون لهم حقيقة. بل حسَّن الشيطان للكفار قولهم الباطل وصدَّهم عن سبيل الله. ومَن لم يوفِّقه الله لهدايته فليس له أحد يهديه، ويوفقه إلى الحق والرشاد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,34,'لهؤلاء الكفار الصادين عن سبيل الله عذاب شاق في الحياة الدنيا بالقتل والأسر والخزي، ولَعذابهم في الآخرة أثقل وأشد، وليس لهم مانع يمنعهم من عذاب الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,35,'صفة الجنة التي وعد الله بها الذين يخشونه أنها تجري من تحت أشجارها وقصورها الأنهار، ثمرها لا ينقطع، وظلها لا يزول ولا ينقص، تلك المثوبة بالجنة عاقبة الذين خافوا الله، فاجتنبوا معاصيه وأدَّوا فرائضه، وعاقبة الكافرين بالله النار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,36,'والذين أعطيناهم الكتاب من اليهود والنصارى مَن آمن منهم بك كعبد الله بن سلام والنجاشي، يستبشرون بالقرآن المنزل عليك لموافقته ما عندهم، ومن المتحزبين على الكفر ضدك، كالسَّيد والعاقب، أُسْقفَي "نجران"، وكعب بن الأشرف، مَن ينكر بعض المنزل عليك، قل لهم: إنما أمرني الله أن أعبده وحده، ولا أشرك به شيئًا، إلى عبادته أدعو الناس، وإليه مرجعي ومآبي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,37,'وكما أنزلنا الكتب على الأنبياء بلسانهم أنزلنا إليك -أيها الرسول- القرآن بلغة العرب؛ لتحكم به، ولئن اتبعت أهواء المشركين في عبادة غير الله -بعد الحق الذي جاءك من الله- ليس لك ناصر ينصرك ويمنعك من عذابه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,38,'وإذا قالوا: ما لك -أيها الرسول- تتزوج النساء؟ فلقد بعثنا قبلك رسلا من البشر وجعلنا لهم أزواجًا وذرية، وإذا قالوا: لو كان رسولا لأتى بما طلبنا من المعجزات، فليس في وُسْع رسولٍ أن يأتي بمعجزةٍ أرادها قومه إلا بإذن الله. لكل أمر قضاه الله كتاب وأجل قد كتبه الله عنده، لا يتقدم ولا يتأخر.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,39,'يمحو الله ما يشاء من الأحكام وغيرها، ويُبْقي ما يشاء منها لحكمة يعلمها، وعنده أمُّ الكتاب، وهو اللوح المحفوظ.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,40,'وإن أريناك -أيها الرسول- بعض العقاب الذي توعَّدْنا به أعداءك من الخزي والنَّكال في الدنيا فذلك المعجَّل لهم، وإن توفيناك قبل أن ترى ذلك، فما عليك إلا تبليغ الدعوة، وعلينا الحساب والجزاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,41,'أولم يبصر هؤلاء الكفار أنا نأتي الأرض ننقصها من أطرافها، وذلك بفتح المسلمين بلاد المشركين وإلحاقها ببلاد المسلمين؟ والله سبحانه يحكم لا معقِّب لحكمه وقضائه، وهو سريع الحساب، فلا يستعجلوا بالعذاب؛ فإن كل آت قريب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,42,'ولقد دبَّر الذين من قبلهم المكايد لرسلهم، كما فعل هؤلاء معك، فلله المكر جميعًا، فيبطل مكرهم، ويعيده عليهم بالخيبة والندم، يعلم سبحانه ما تكسب كل نفس من خير أو شر فتجازى عليه. وسيعلم الكفار -إذا قدموا على ربهم- لمن تكون العاقبة المحمودة بعد هذه الدنيا؟ إنها لأتباع الرسل. وفي هذا تهديد ووعيد للكافرين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),13,43,'ويقول الذين كفروا لنبي الله: -يا محمد- ما أرسلك الله، قل لهم: كفى بالله شهيدًا بصدقي وكذبكم، وكَفَتْ شهادة مَن عنده علم الكتاب من اليهود والنصارى ممن آمن برسالتي، وما جئتُ به من عند الله، واتبع الحق فصرَّح بتلك الشهادة، ولم يكتمها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/13/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=13) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,1,'(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,2,'(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,3,'وهؤلاء الذين أعرضوا ولم يؤمنوا بالله ويتبعوا رسله هم الذين يختارون الحياة الدنيا الفانية، ويتركون الآخرة الباقية، ويمنعون الناس عن اتباع دين الله، ويريدونه طريقًا معوجًا ليوافق أهواءهم، أولئك الموصوفون بهذه الصفات في ضلال عن الحق بعيد عن كل أسباب الهداية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,4,'وما أرسلنا مِن رسولٍ قبلك -أيها النبي- إلا بلُغة قومه؛ ليوضِّح لهم شريعة الله، فيضل الله من يشاء عن الهدى، ويهدي من يشاء إلى الحق، وهو العزيز في ملكه، الحكيم الذي يضع الأمور في مواضعها وَفْق الحكمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,5,'ولقد أرسلنا موسى إلى بني إسرائيل وأيدناه بالمعجزات الدالة على صدقه، وأمرناه بأن يدعوهم إلى الإيمان؛ ليخرجهم من الضلال إلى الهدى، ويذكِّرهم بنعم الله ونقمه في أيامه، إن في هذا التذكير بها لَدلالات لكل صبَّار على طاعة الله، وعن محارمه، وعلى أقداره، شكور قائم بحقوق الله، يشكر الله على نعمه، وخصَّهم بذلك؛ لأنهم هم الذين يعتبرون بها، ولا يَغْفُلون عنها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,6,'واذكر -أيها الرسول- لقومك قصة موسى حين قال لبني إسرائيل: اذكروا نعمة الله عليكم حين أنجاكم من فرعون وأتباعه يذيقونكم أشد العذاب، ويذبِّحون أبناءكم الذكور، حتى لا يأتي منهم من يستولي على مُلْك فرعون، ويبقون الإناث على قيد الحياة ذليلات، وفي ذلكم البلاء والإنجاء اختبار لكم من ربكم عظيم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,7,'وقال لهم موسى: واذكروا حين أعلم ربكم إعلامًا مؤكَّدًا: لئن شكرتموه على نعمه ليزيدنكم من فضله، ولئن جحدتم نعمة الله ليعذبنَّكم عذابًا شديدًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,8,'وقال لهم: إن تكفروا بالله أنتم وجميع أهل الأرض فلن تضروا الله شيئًا؛ فإن الله لغني عن خلقه، مستحق للحمد والثناء، محمود في كل حال.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,9,'ألم يأتكم -يا أمَّة محمد- خبر الأمم التي سبقتكم، قوم نوح وقوم هود وقوم صالح، والأمم التي بعدهم، لا يحصي عددهم إلا الله، جاءتهم رسلهم بالبراهين الواضحات، فعضُّوا أيديهم غيظًا واستنكافًا عن قَبول الإيمان، وقالوا لرسلهم: إنا لا نصدِّق بما جئتمونا به، وإنا لفي شكٍّ مما تدعوننا إليه من الإيمان والتوحيد موجب للريبة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,10,'قالت لهم رسلهم: أفي الله وعبادته -وحده- ريب، وهو خالق السموات والأرض، ومنشئهما من العدم على غير مثال سابق، وهو يدعوكم إلى الإيمان؛ ليغفر لكم ذنوبكم، ويؤخر بقاءكم في الدنيا إلى أجل قدَّره، وهو نهاية آجالكم، فلا يعذبكم في الدنيا؟ فقالوا لرسلهم: ما نراكم إلا بشرًا صفاتكم كصفاتنا، لا فضل لكم علينا يؤهلكم أن تكونوا رسلا. تريدون أن تمنعونا من عبادة ما كان يعبده آباونا من الأصنام والأوثان، فأتونا بحجة ظاهرة تشهد على صحة ما تقولون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,11,'ولما سمع الرسل ما قاله أقوامهم قالوا لهم: حقًا ما نحن إلا بشر مثلكم كما قلتم، ولكن الله يتفضل بإنعامه على مَن يشاء من عباده فيصطفيهم لرسالته، وما طلبتم من البرهان المبين، فلا يمكن لنا ولا نستطيع أن نأتيكم به إلا بإذن الله وتوفيقه، وعلى الله وحده يعتمد المؤمنون في كل أمورهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,12,'وكيف لا نعتمد على الله، وهو الذي أرشدنا إلى طريق النجاة من عذابه باتباع أحكام دينه؟ ولنصبرنَّ على إيذائكم لنا بالكلام السيئ وغيره، وعلى الله وحده يجب أن يعتمد المؤمنون في نصرهم، وهزيمة أعدائهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,13,'وضاقت صدور الكفار مما قاله الرسل فقالوا لهم: لنطردنكم من بلادنا حتى تعودوا إلى ديننا، فأوحى الله إلى رسله أنه سيهلك الجاحدين الذين كفروا به وبرسله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,14,'ولنجعلن العاقبة الحسنة للرسل وأتباعهم بإسكانهم أرض الكافرين بعد إهلاكهم، ذلك الإهلاك للكفار، وإسكان المؤمنين أرضهم أمر مؤكد لمن خاف مقامه بين يديَّ يوم القيامة، وخشي وعيدي وعذابي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,15,'ولجأ الرسل إلى ربهم وسألوه النصر على أعدائهم والحكم بينهم، فاستجاب لهم، وهلك كل متكبر لا يقبل الحق ولا يُذْعن له، ولا يقر بتوحيد الله وإخلاص العبادة له.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,16,'ومِن أمام هذا الكافر جهنم يَلْقى عذابها؛ ويُسقى فيها من القيح والدم الذي يَخْرج من أجسام أهل النار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,17,'يحاول المتكبر ابتلاع القيح والدم وغير ذلك مما يسيل من أهل النار مرة بعد مرة، فلا يستطيع أن يبتلعه؛ لقذارته وحرارته، ومرارته، ويأتيه العذاب الشديد من كل نوع ومن كل عضو من جسده، وما هو بميت فيستريح، وله من بعد هذا العذاب عذاب آخر مؤلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,18,'صفة أعمال الكفار في الدنيا كالبر وصلة الأرحام كصفة رماد اشتدت به الريح في يوم ذي ريح شديدة، فلم تترك له أثرًا، فكذلك أعمالهم لا يجدون منها ما ينفعهم عند الله، فقد أذهبها الكفر كما أذهبت الريح الرماد، ذلك السعي والعمل على غير أساس، هو الضلال البعيد عن الطريق المستقيم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,19,'ألم تعلم أيها المخاطب -والمراد عموم الناس- أن الله أوجد السموات والأرض على الوجه الصحيح الدال على حكمته، وأنه لم يخلقهما عبثًا، بل للاستدلال بهما على وحدانيته، وكمال قدرته، فيعبدوه وحده، ولا يشركوا به شيئًا؟ إن يشأ يذهبكم ويأت بقوم غيركم يطيعون الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,20,'وما إهلاككم والإتيان بغيركم بممتنع على الله، بل هو سهل يسير.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,21,'وخرجت الخلائق من قبورهم، وظهروا كلهم يوم القيامة لله الواحد القهار؛ ليحكم بينهم، فيقول الأتباع لقادتهم: إنَّا كنَّا لكم في الدنيا أتباعًا، نأتمر بأمركم، فهل أنتم -اليوم- دافعون عنا من عذاب الله شيئًا كما كنتم تَعِدوننا؟ فيقول الرؤساء: لو هدانا الله إلى الإيمان لأرشدناكم إليه، ولكنه لم يوفقنا، فضللنا وأضللناكم، يستوي علينا وعليكم الـجَزَع والصبر عليه، فليس لنا مهرب من العذاب ولا منجى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,22,'وقال الشيطان -بعد أن قضى الله الأمر وحاسب خَلْقه، ودخل أهلُ الجنة الجنةَ وأهلُ النارِ النارَ-: إن الله وعدكم وعدًا حقًا بالبعث والجزاء، ووعدتكم وعدًا باطلا أنه لا بَعْثَ ولا جزاء، فأخلفتكم وعدي، وما كان لي عليكم من قوة أقهركم بها على اتباعي، ولا كانت معي حجة، ولكن دعوتكم إلى الكفر والضلال فاتبعتموني، فلا تلوموني ولوموا أنفسكم، فالذنب ذنبكم، ما أنا بمغيثكم ولا أنتم بمغيثيَّ من عذاب الله، إني تبرَّأت مِن جَعْلِكم لي شريكًا مع الله في طاعته في الدنيا. إن الظالمين -في إعراضهم عن الحق واتباعهم الباطل- لهم عذاب مؤلم موجع.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,23,'وأُدخل الذين صدَّقوا الله ورسوله وعملوا الصالحات جنات تجري من تحت أشجارها وقصورها الأنهار، لا يخرجون منها أبدًا -بإذن ربهم وحوله وقوته- يُحَيَّوْن فيها بسلام من الله وملائكته والمؤمنين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,24,'ألم تعلم -أيها الرسول- كيف ضرب الله مثلا لكلمة التوحيد (لا إله إلا الله) بشجرة عظيمة، وهي النخلة، أصلها متمكن في الأرض، وأعلاها مرتفع علوًّا نحو السماء؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,25,'تعطي ثمارها كل وقت بإذن ربها، وكذلك شجرة الإيمان أصلها ثابت في قلب المؤمن علمًا واعتقادًا، وفرعها من الأعمال الصالحة والأخلاق المرضية يُرفع إلى الله وينال ثوابه في كل وقت. ويضرب الله الأمثال للناس؛ ليتذكروا ويتعظوا، فيعتبروا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,26,'ومثل كلمة خبيثة -وهي كلمة الكفر- كشجرة خبيثة المأكل والمطعم، وهي شجرة الحنظل، اقتلعت من أعلى الأرض؛ لأن عروقها قريبة من سطح الأرض ما لها أصل ثابت، ولا فرع صاعد، وكذلك الكافر لا ثبات له ولا خير فيه، ولا يُرْفَع له عمل صالح إلى الله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,27,'يثبِّت الله الذين آمنوا بالقول الحق الراسخ، وهو شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وما جاء به من الدين الحق يثبتهم الله به في الحياة الدنيا، وعند مماتهم بالخاتمة الحسنة، وفي القبر عند سؤال المَلَكين بهدايتهم إلى الجواب الصحيح، ويضل الله الظالمين عن الصواب في الدنيا والآخرة، ويفعل الله ما يشاء من توفيق أهل الإيمان وخِذْلان أهل الكفر والطغيان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,28,'ألم تنظر أيها المخاطب -والمراد العموم- إلى حال المكذبين من كفار قريش الذين استبدلوا الكفر بالله بدلا عن شكره على نعمة الأمن بالحرم وبعثة النبي محمد صلى الله عليه وسلم فيهم؟ وقد أنـزلوا أتباعهم دار الهلاك حين تَسببوا بإخراجهم إلى "بدر" فقُتِلوا وصار مصيرهم دار البوار، وهي جهنم، يدخلونها ويقاسون حرها، وقَبُحَ المستقر مستقرهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,29,'ألم تنظر أيها المخاطب -والمراد العموم- إلى حال المكذبين من كفار قريش الذين استبدلوا الكفر بالله بدلا عن شكره على نعمة الأمن بالحرم وبعثة النبي محمد صلى الله عليه وسلم فيهم؟ وقد أنـزلوا أتباعهم دار الهلاك حين تَسببوا بإخراجهم إلى "بدر" فقُتِلوا وصار مصيرهم دار البوار، وهي جهنم، يدخلونها ويقاسون حرها، وقَبُحَ المستقر مستقرهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,30,'وجعل هؤلاء الكفار لله شركاء عبدوهم معه؛ ليُبْعدوا الناس عن دينه. قل لهم -أيها الرسول-: استمتعوا في الحياة الدنيا؛ فإنها سريعة الزوال، وإن مردَّكم ومرجعكم إلى عذاب جهنم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,31,'قل -أيها الرسول- لعبادي الذين آمنوا: يؤدوا الصلاة بحدودها، ويخرجوا بعض ما أعطيناهم من المال في وجوه الخير الواجبة والمستحبة مسرِّين ذلك ومعلنين، من قبل أن يأتي يوم القيامة الذي لا ينفع فيه فداء ولا صداقة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,32,'الله تعالى الذي خلق السموات والأرض وأوجدهما من العدم، وأنزل المطر من السحاب فأحيا به الأرض بعد موتها، وأخرج لكم منها أرزاقكم، وذلَّل لكم السفن؛ لتسير في البحر بأمره لمنافعكم، وذلَّل لكم الأنهار لسقياكم وسقيا دوابكم وزروعكم وسائر منافعكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,33,'وذلَّل الله لكم الشمس والقمر لا يَفْتُران عن حركتهما؛ لتتحقق المصالح بهما، وذلَّل لكم الليل؛ لتسكنوا فيه وتستريحوا، والنهار؛ لتبتغوا من فضله، وتدبِّروا معايشكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,34,'وأعطاكم من كل ما طلبتموه، وإن تعدُّوا نِعَم الله عليكم لا تطيقوا عدها ولا إحصاءها ولا القيام بشكرها؛ لكثرتها وتنوُّعها. إن الإنسان لَكثير الظلم لنفسه، كثير الجحود لنعم ربه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,35,'واذكر -أيها الرسول- حين قال إبراهيم داعيًا ربه -بعد أن أسكن ابنه إسماعيل وأمه "هاجَر" وادي "مكة" -: رب اجعل "مكة" بلدَ أمنٍ يأمن كل مَن فيها، وأبعِدني وأبنائي عن عبادة الأصنام.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,36,'ربِّ إن الأصنام تسبَّبتْ في إبعاد كثير من الناس عن طريق الحق، فمن اقتدى بي في التوحيد فهو على ديني وسُنَّتي، ومَن خالفني فيما دون الشرك، فإنك غفور لذنوب المذنبين -بفضلك- رحيم بهم، تعفو عمن تشاء منهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,37,'ربنا إني أسكنت من ذريتي بوادٍ ليس فيه زرع ولا ماء بجوار بيتك المحرم، ربنا إنني فعلت ذلك بأمرك؛ لكي يؤدوا الصلاة بحدودها، فاجعل قلوب بعض خلقك تَنزع إليهم وتحنُّ، وارزقهم في هذا المكان من أنواع الثمار؛ لكي يشكروا لك على عظيم نعمك. فاستجاب الله دعاءه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,38,'ربنا إنك تعلم كل ما نخفيه وما نظهره. وما يغيب عن علم الله شيء من الكائنات في الأرض ولا في السماء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,39,'يُثْني إبراهيم على الله تعالى، فيقول: الحمد لله الذي رزقني على كِبَر سني ولديَّ إسماعيل وإسحاق بعد دعائي أن يهب لي من الصالحين، إن ربي لسميع الدعاء ممن دعاه، وقد دعوته ولم يخيِّب رجائي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,40,'رب اجعلني مداومًا على أداء الصلاة على أتم وجوهها، واجعل من ذريتي مَن يحافظ عليها، ربنا واستجب دعائي وتقبَّل عبادتي.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,41,'ربنا اغفر لي ما وقع مني مما لا يسلم منه البشر واغفر لوالديَّ، (وهذا قبل أن يتبيَّن له أن والده عدو لله) واغفر للمؤمنين جميعًا يوم يقوم الناس للحساب والجزاء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,42,'ولا تحسبن -أيها الرسول- أن الله غافل عما يعمله الظالمون: من التكذيب بك وبغيرك من الرسل، وإيذاء المؤمنين وغير ذلك من المعاصي، إنما يؤخِّرُ عقابهم ليوم شديد ترتفع فيه عيونهم ولا تَغْمَض؛ مِن هول ما تراه. وفي هذا تسلية لرسول الله محمد صلى الله عليه وسلم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,43,'يوم يقوم الظالمون من قبورهم مسرعين لإجابة الداعي رافعي رؤوسهم لا يبصرون شيئًا لهول الموقف، وقلوبهم خالية ليس فيها شيء؛ لكثرة الخوف والوجل من هول ما ترى.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,44,'وأنذر -أيها الرسول- الناس الذين أرسلتُكَ إليهم عذاب الله يوم القيامة، وعند ذلك يقول الذين ظلموا أنفسهم بالكفر: ربنا أَمْهِلْنا إلى وقت قريب نؤمن بك ونصدق رسلك. فيقال لهم توبيخًا: ألم تقسموا في حياتكم أنه لا زوال لكم عن الحياة الدنيا إلى الآخرة، فلم تصدِّقوا بهذا البعث؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,45,'وحللتم في مساكن الكافرين السابقين الذين ظلموا أنفسهم كقوم هود وصالح، وعلمتم -بما رأيتم وأُخبرتم- ما أنزلناه بهم من الهلاك، وضربنا لكم الأمثال في القرآن، فلم تعتبروا؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,46,'وقد دبَّر المشركون الشرَّ للرسول صلى الله عليه وسلم بقتله، وعند الله مكرهم فهو محيط به، وقد عاد مكرهم عليهم، وما كان مكرهم لتزول منه الجبال ولا غيرها لضعفه ووَهَنه، ولم يضرُّوا الله شيئًا، وإنما ضرُّوا أنفسهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,47,'فلا تحسبن -أيها الرسول- أن الله يخلف رسله ما وعدهم به من النصر وإهلاك مكذبيهم. إن الله عزيز لا يمتنع عليه شيء، منتقم من أعدائه أشد انتقام. والخطاب وإن كان خاصًّا بالنبي صلى الله عليه وسلم، فهو موجَّه لعموم الأمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,48,'وانتقام الله تعالى مِن أعدائه في يوم القيامة يوم تُبَدَّل هذه الأرض بأرض أخرى بيضاء نقيَّة كالفضة، وكذلك تُبَدَّل السموات بغيرها، وتخرج الخلائق من قبورها أحياء ظاهرين للقاء الله الواحد القهار، المتفرد بعظمته وأسمائه وصفاته وأفعاله وقهره لكل شيء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,49,'وتُبْصِرُ -أيها الرسول- المجرمين يوم القيامة مقيدين بالقيود، قد قُرِنت أيديهم وأرجلهم بالسلاسل، وهم في ذُلٍّ وهوان.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,50,'ثيابهم من القَطِران الشديد الاشتعال، وتلفح وجوههم النار فتحرقها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,51,'فَعَل الله ذلك بهم؛ جزاء لهم بما كسبوا من الآثام في الدنيا، والله يجازي كل إنسان بما عمل مِن خير أو شر، إن الله سريع الحساب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),14,52,'هذا القرآن الذي أنزلناه إليك -أيها الرسول- بلاغ وإعلام للناس؛ لنصحهم وتخويفهم، ولكي يوقنوا أن الله هو الإله الواحد، فيعبدوه وحده لا شريك له، وليتعظ به أصحاب العقول السليمة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/14/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=14) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,1,'(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,2,'سيتمنى الكفار حين يرون خروج عصاة المؤمنين من النار أن لو كانوا موحدين؛ ليخرجوا كما خرجوا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,3,'اترك -أيها الرسول- الكفار يأكلوا، ويستمتعوا بدنياهم، ويشغلهم الطمع فيها عن طاعة الله، فسوف يعلمون عاقبة أمرهم الخاسرة في الدنيا والآخرة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,4,'وإذا طلبوا نزول العذاب بهم تكذيبًا لك -أيها الرسول- فإنا لا نُهْلك قرية إلا ولإهلاكها أجل مقدَّر، لا نُهْلكهم حتى يبلغوه، مثل مَن سبقهم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,5,'لا تتجاوز أمة أجلها فتزيد عليه، ولا تتقدم عليه، فتنقص منه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,6,'وقال المكذبون لمحمد صلى الله عليه وسلم استهزاءً: يا أيها الذي نُزِّل عليه القرآن إنك لذاهب العقل، هلا تأتينا بالملائكة -إن كنت صادقًا-؛ لتشهد أن الله أرسلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,7,'وقال المكذبون لمحمد صلى الله عليه وسلم استهزاءً: يا أيها الذي نُزِّل عليه القرآن إنك لذاهب العقل، هلا تأتينا بالملائكة -إن كنت صادقًا-؛ لتشهد أن الله أرسلك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,8,'وردَّ الله عليهم: إننا لا ننزل الملائكة إلا بالعذاب الذي لا إمهال فيه لمن لم يؤمن، وما كانوا حين تنزل الملائكة بالعذاب بِمُمْهلين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,9,'إنَّا نحن نزَّلنا القرآن على النبي محمد صلى الله عليه وسلم، وإنَّا نتعهد بحفظه مِن أن يُزاد فيه أو يُنْقَص منه، أو يضيع منه شيء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,10,'ولقد أرسلنا من قبلك -أيها الرسول- رسلا في فِرَق الأولين، فما من رسولٍ جاءهم إلا كانوا منه يسخرون. وفي هذا تسلية للرسول صلى الله عليه وسلم. فكما فَعَل بك هؤلاء المشركون فكذلك فُعِلَ بمن قبلك من الرسل.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,11,'ولقد أرسلنا من قبلك -أيها الرسول- رسلا في فِرَق الأولين، فما من رسولٍ جاءهم إلا كانوا منه يسخرون. وفي هذا تسلية للرسول صلى الله عليه وسلم. فكما فَعَل بك هؤلاء المشركون فكذلك فُعِلَ بمن قبلك من الرسل.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,12,'كما أدخلنا الكفر في قلوب الأمم السابقة بالاستهزاء بالرسل وتكذيبهم، كذلك نفعل ذلك في قلوب مشركي قومك الذين أجرموا بالكفر بالله وتكذيب رسوله، لا يُصَدِّقون بالذكر الذي أُنزل إليك، وقد مضت سنَّة الأولين بإهلاك الكفار، وهؤلاء مِثْلهم، سَيُهْلك المستمرون منهم على الكفر والتكذيب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,13,'كما أدخلنا الكفر في قلوب الأمم السابقة بالاستهزاء بالرسل وتكذيبهم، كذلك نفعل ذلك في قلوب مشركي قومك الذين أجرموا بالكفر بالله وتكذيب رسوله، لا يُصَدِّقون بالذكر الذي أُنزل إليك، وقد مضت سنَّة الأولين بإهلاك الكفار، وهؤلاء مِثْلهم، سَيُهْلك المستمرون منهم على الكفر والتكذيب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,14,'ولو فتحنا على كفار "مكة" بابًا من السماء فاستمروا صاعدين فيه حتى يشاهدوا ما في السماء من عجائب ملكوت الله، لما صدَّقوا، ولقالوا: سُحِرَتْ أبصارنا، حتى رأينا ما لم نرَ، وما نحن إلا مسحورون في عقولنا من محمد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,15,'ولو فتحنا على كفار "مكة" بابًا من السماء فاستمروا صاعدين فيه حتى يشاهدوا ما في السماء من عجائب ملكوت الله، لما صدَّقوا، ولقالوا: سُحِرَتْ أبصارنا، حتى رأينا ما لم نرَ، وما نحن إلا مسحورون في عقولنا من محمد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,16,'ومن أدلة قدرتنا: أنا جعلنا في السماء الدنيا منازل للكواكب تنزل فيها، ويستدل بذلك على الطرقات والأوقات والخِصْب والجَدْب، وزَيَّنَّا هذه السماء بالنجوم لمن ينظرون إليها، ويتأملون فيعتبرون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,17,'وحفظنا السماء من كل شيطان مرجوم مطرود من رحمة الله؛ كي لا يصل إليها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,18,'إلا من اختلس السمع مِن كلام أهل الملأ الأعلى في بعض الأوقات، فأدركه ولحقه كوكب مضيء يحرقه. وقد يُلْقي الشيطان إلى وليه بعض ما استرقَه قبل أن يحرقه الشهاب.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,19,'والأرض مددناها متسعة، وألقينا فيها جبالا تثبتها، وأنبتنا فيها من كل أنواع النبات ما هو مقدَّر معلوم مما يحتاج إليه العباد.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,20,'وجعلنا لكم فيها ما به تعيشون من الحَرْث، ومن الماشية، ومن أنواع المكاسب وغيرها، وخلقنا لكم من الذرية والخدم والدوابِّ ما تنتفعون به، وليس رزقهم عليكم، وإنما هو على الله رب العالمين تفضلا منه وتكرمًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,21,'وما من شيء من منافع العباد إلا عندنا خزائنه من جميع الصنوف، وما ننزله إلا بمقدار محدد كما نشاء وكما نريد، فالخزائن بيد الله يعطي من يشاء ويمنع من يشاء، بحسب رحمته الواسعة، وحكمته البالغة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,22,'وأرسلنا الرياح وسخرناها تُلَقِّح السحاب، وتحمل المطر والخير والنفع، فأنزلنا من السحاب ماء أعددناه لشرابكم وأرضكم ومواشيكم، وما أنتم بقادرين على خزنه وادِّخاره، ولكن نخزنه لكم رحمة بكم، وإحسانًا إليكم.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,23,'وإنَّا لنحن نحيي مَن كان ميتًا بخلقه من العدم، ونميت من كان حيًا بعد انقضاء أجله، ونحن الوارثون الأرض ومَن عليها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,24,'ولقد علمنا مَن هلك منكم مِن لدن آدم، ومَن هو حيٌّ، ومَن سيأتي إلى يوم القيامة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,25,'وإن ربك هو يحشرهم للحساب والجزاء، إنه حكيم في تدبيره، عليم لا يخفى عليه شيء.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,26,'ولقد خلقنا آدم مِن طين يابس إذا نُقِر عليه سُمع له صوت، وهذا الطين اليابس من طين أسود متغيِّر لونه وريحه؛ مِن طول مكثه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,27,'وخلقنا أبا الجن، وهو إبليس مِن قَبْل خلق آدم من نار شديدة الحرارة لا دخان لها.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,28,'واذكر -أيها النبي- حين قال ربك للملائكة: إني خالق إنسانًا من طين يابس، وهذا الطين اليابس من طين أسود متغيِّر اللون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,29,'فإذا سوَّيته وأكملت صورته ونفخت فيه الروح، فخُرُّوا له ساجدين سجود تحية وتكريم، لا سجود عبادة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),15,30,'فسجد الملائكة كلهم أجمعون كما أمرهم ربهم لم يمتنع منهم أحد، لكن إبليس امتنع أن يسجد لآدم مع الملائكة الساجدين.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/15/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=15) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
